const CHAPTERS: VizChapter[] = [{"id":"db-ch01","subj":"database","title":"关系模型与 SQL 基础（DDL/DML/SELECT/JOIN/聚合/分组）","summary":"关系模型基本概念（表/行/列/主键/外键）；DDL 建表改表删表；DML 增删改；SELECT 查询、WHERE 过滤、ORDER BY、LIMIT；INNER/LEFT/RIGHT JOIN；聚合函数与 GROUP BY、HAVING 分…","concepts":[{"id":"db-ch01/01-relational-model","file":"01-relational-model.md","title":"01 · 关系模型基本概念","kind":"flow","secs":[{"h":"一、术语对照：数学 ↔ 表","s":"关系模型的三个核心要求：属性原子（不可再分）、元组无序、属性无序（但 SQL 表有物理顺序与列顺序，这是实现补充，不是模型要求）。","c":null},{"h":"二、键的四层概念","s":"这是考试与设计都绕不开的一组定义，层层收窄：","c":{"lang":"text","code":"超键 ⊃ 候选键 ⊃ 主键\n超键：能唯一标识一行的属性集合（可含多余属性）\n候选键：最小超键 —— 去掉任一属性就不再唯一\n主键：从候选键中选定的一个\n外键：引用另一张表主键（或候选键）的属性，用于表达表间关联"}},{"h":"三、三类完整性约束","s":"一个常被忽略的细节：外键列允许 NULL，且 NULL 不参与参照完整性检查（\"不知道\"不等于\"不存在\"）。所以\"可选关联\"用可空外键表达是合法的。","c":null},{"h":"四、关系代数：SQL 的语义内核","s":"五种基本运算（其余都可由它们导出）：","c":{"lang":"text","code":"关系代数 → SQL 的映射（注意去重语义）\n\n  σ_{salary>5000}(employee)        →  WHERE salary > 5000\n  π_{name}(employee)               →  SELECT DISTINCT name\n  employee ⋈_{dept_id} dept        →  INNER JOIN ... ON ...\n  A ∪ B                            →  UNION（去重） / UNION ALL（不去重）\n  A − B                            →  EXCEPT（MySQL 8.0.31+ 支持）"}},{"h":"五、NULL：三值逻辑的代价","s":"NULL 表示\"未知/不适用\"，不是 0、不是空串。它引入了三值逻辑：","c":{"lang":"sql","code":"-- 想查\"部门不是 20 的员工\"，会漏掉 dept_id 为 NULL 的人\nSELECT * FROM employee WHERE dept_id <> 20;\n\n-- 正确写法：显式包含 NULL\nSELECT * FROM employee WHERE dept_id <> 20 OR dept_id IS NULL;"}},{"h":"六、范式：从 1NF 到 3NF（够用版）","s":"工程实践通常停在 3NF，再按查询性能做受控冗余（反范式）。范式的目标是消除更新异常（插入/删除/修改异常），不是\"越规范越好\"。","c":null},{"h":"七、边界与陷阱","s":"","c":null},{"h":"八、可运行示例：三值逻辑与 1NF 违例","s":"最后一条查询返回空：Bob 的 dept_id 是 NULL，NULL NOT IN (10, 20) 求值为 UNKNOWN，被 WHERE 丢弃；Alice 的 10 在集合里，结果是 FALSE。两侧都可能出问题——若子查询结果本…","c":{"lang":"sql","code":"CREATE TABLE department (\n    dept_id   INT PRIMARY KEY,\n    dept_name VARCHAR(20) NOT NULL,\n    location  VARCHAR(20)\n);\n\nCREATE TABLE employee (\n    emp_id  INT PRIMARY KEY,\n    name    VARCHAR(20) NOT NULL,\n…"}},{"h":"九、小结：把关系模型压缩成四个判断","s":"学完这一章，真正需要带走的是四个判断，而不是一张术语表。","c":null}]},{"id":"db-ch01/02-sql-ddl-dml","file":"02-sql-ddl-dml.md","title":"02 · DDL 与 DML（建表、改表与增删改）","kind":"flow","secs":[{"h":"一、SQL 的五大类","s":"TRUNCATE 归 DDL 是个常见误解点：它按页释放数据、不写逐行 undo，因此不能回滚、会重置自增、不触发行级触发器。","c":null},{"h":"二、DDL：定义结构","s":"生产上给大表加列/改类型必须走 ALGORITHM=INPLACE/INSTANT 或外部工具（gh-ost、pt-online-schema-change），别在业务高峰直接 ALTER。","c":{"lang":"sql","code":"-- 建表\nCREATE TABLE employee (\n    emp_id  INT PRIMARY KEY AUTO_INCREMENT,\n    name    VARCHAR(20) NOT NULL,\n    dept_id INT,\n    salary  DECIMAL(10,2) NOT NULL DEFAULT 0.00,\n    hired   DATE,\n    status  TINYINT NOT NULL DEFAULT 1,\n    CONSTRAINT fk_emp_dept FOREIGN KEY (dept_id) REFERENCES department(dept_id)\n…"}},{"h":"三、DML：增删改","s":"命中主键/唯一键冲突时转为更新。注意它依赖唯一约束的存在，且自增主键会被消耗（冲突也会推进 AUTO_INCREMENT）。MySQL 8.0.20 起推荐用别名语法 AS new 代替已废弃的 VALUES()。","c":{"lang":"sql","code":"-- 插入（显式列名最稳妥：加列后旧语句不会错位）\nINSERT INTO employee (emp_id, name, dept_id, salary)\nVALUES (1, 'Alice', 10, 6000.00),\n       (2, 'Bob',   20, 8000.00);\n\n-- 从查询结果插入\nINSERT INTO employee_archive (emp_id, name)\nSELECT emp_id, name FROM employee WHERE status = 0;\n\n…"}},{"h":"四、数据类型的选择：四个关键判断","s":"二进制浮点无法精确表示 0.1（0.1 是二进制无限循环小数），累加会产生误差；DECIMAL(10,2) 是十进制定点表示，语义精确。这是\"数值表示\"问题，不是数据库问题。","c":null},{"h":"五、UPDATE / DELETE 的安全流程","s":"1. 先 SELECT 同条件，确认行数与内容符合预期。","c":{"lang":"text","code":"危险语句的检查清单\n\n  UPDATE / DELETE\n    ├─ 有 WHERE 吗？          无 → 全表操作，事故\n    ├─ WHERE 用到索引吗？      否 → 锁全表扫描的行\n    ├─ 影响行数是多少？        超大 → 拆批\n    └─ 在事务里吗？            是 → 注意长事务与 undo 膨胀"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：建表、UPSERT 与安全更新","s":"DECIMAL(10,2) 保证 balance 的加减精确到分；AS new 别名语法是 MySQL 8.0.20+ 的推荐写法（旧的 VALUES(col) 已废弃）。","c":{"lang":"sql","code":"CREATE TABLE account (\n    id      INT PRIMARY KEY,\n    owner   VARCHAR(20) NOT NULL,\n    balance DECIMAL(10,2) NOT NULL DEFAULT 0.00,\n    status  TINYINT NOT NULL DEFAULT 1,\n    UNIQUE KEY uk_owner (owner)\n);\n\nINSERT INTO account (id, owner, balance) VALUES (1,'Alice',1000.00), (2,'Bob',500.00);\n…"}},{"h":"八、小结：DDL 与 DML 的边界感","s":"这一章最容易记住、也最容易被忽略的一句话是：DDL 改结构，DML 改数据，两者代价的性质完全不同。","c":null}]},{"id":"db-ch01/03-select-join-aggregate","file":"03-select-join-aggregate.md","title":"03 · SELECT 查询、JOIN 关联与聚合分组","kind":"flow","secs":[{"h":"SELECT 基本结构","s":"执行逻辑顺序（理解它才能写好查询）：FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT。","c":{"lang":"sql","code":"SELECT name, salary\nFROM employee\nWHERE salary > 5000\nORDER BY salary DESC\nLIMIT 3;"}},{"h":"一、两个顺序，别搞混","s":"注意\"逻辑顺序\"不等于\"物理执行顺序\"：优化器会在保持语义等价的前提下重排（选择下推、谓词合并）。但语义判定永远按逻辑顺序解释。","c":{"lang":"text","code":"书写顺序                    逻辑执行顺序\nSELECT                       FROM / JOIN\n  ↓                            ↓\nFROM                         WHERE\n  ↓                            ↓\nWHERE                        GROUP BY\n  ↓                            ↓\nGROUP BY                     HAVING\n  ↓                            ↓\n…"}},{"h":"二、JOIN 全景","s":"这是\"数据莫名变少\"的第一嫌疑点。规则：想保留左表全部行，就把右表的过滤条件放 ON。","c":{"lang":"sql","code":"-- INNER JOIN：只要匹配上的\nSELECT e.name, d.dept_name\nFROM employee e\nINNER JOIN department d ON e.dept_id = d.dept_id;\n\n-- LEFT JOIN：保留所有员工，没部门的 dept_name 为 NULL\nSELECT e.name, d.dept_name\nFROM employee e\nLEFT JOIN department d ON e.dept_id = d.dept_id;\n…"}},{"h":"三、聚合与分组","s":"这带来两个反直觉结果：","c":{"lang":"sql","code":"SELECT dept_id,\n       COUNT(*)             AS headcount,\n       ROUND(AVG(salary),2) AS avg_salary,\n       MAX(salary)          AS top_salary\nFROM employee\nGROUP BY dept_id\nHAVING AVG(salary) > 7000\nORDER BY avg_salary DESC;"}},{"h":"四、子查询的三种形态","s":"","c":{"lang":"sql","code":"-- 标量子查询：返回单值\nSELECT name, salary FROM employee\nWHERE salary > (SELECT AVG(salary) FROM employee);\n\n-- 行/列子查询 + IN\nSELECT name FROM employee WHERE dept_id IN (SELECT dept_id FROM department WHERE location='Beijing');\n\n-- 相关子查询（EXISTS）：对外层每一行执行一次\nSELECT d.dept_name FROM department d\n…"}},{"h":"五、窗口函数：分组的\"不折叠\"版本","s":"GROUP BY 会把多行折叠成一行；只想\"在每行旁边显示分组统计\"时用窗口函数：","c":{"lang":"sql","code":"SELECT name, dept_id, salary,\n       AVG(salary) OVER (PARTITION BY dept_id) AS dept_avg,\n       RANK()       OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rk\nFROM employee;"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：JOIN 语义与聚合口径","s":"第三段用 UNION ALL 把两种过滤方式并排输出，能直接看到 where_filter 那组少了\"没有部门/部门不在北京\"的员工——这就是\"LEFT JOIN 退化\"的观测方式。","c":{"lang":"sql","code":"-- 两种 JOIN 的差异\nSELECT e.name, d.dept_name\nFROM employee e INNER JOIN department d ON e.dept_id = d.dept_id\nORDER BY e.name;\n\nSELECT e.name, d.dept_name\nFROM employee e LEFT JOIN department d ON e.dept_id = d.dept_id\nORDER BY e.name;\n\n…"}},{"h":"八、小结：查询的三层心智模型","s":"写复杂 SQL 时，脑子里保留三层结构，比一条条子句往下顺要可靠得多。","c":null}]}],"exams":[{"kind":"choice","q":"关于 INNER JOIN 与 LEFT JOIN 的描述，正确的是","stem":"给定 employee（emp_id, dept_id）与 department（dept_id, dept_name），选择正确的描述。","opts":[{"k":"A","t":"LEFT JOIN 只返回两表都能匹配上的行"},{"k":"B","t":"INNER JOIN 只返回两表都能匹配上的行；LEFT JOIN 还会保留左表中无匹配的行（右表列补 NULL）"},{"k":"C","t":"LEFT JOIN 与 RIGHT JOIN 在交换两表顺序后结果一定相同"},{"k":"D","t":"JOIN 默认是 LEFT JOIN"}],"ans":"B","why":"INNER JOIN 取交集；LEFT JOIN 以左表为基准保留全部左表行，右表无匹配补 NULL；JOIN 默认是 INNER JOIN。"},{"kind":"fix_error","q":"修复 ONLY_FULL_GROUP_BY 报错","stem":"以下查询在 MySQL 5.7+ 开启 ONLY_FULL_GROUP_BY 时直接报错，请修复： sql SELECT dept_id, name, COUNT() AS cnt FROM employee GROUP BY dept_id;","opts":[],"ans":"SELECT dept_id, GROUP_CONCAT(name) AS names, COUNT() AS cnt FROM employee GROUP BY dept_id;","why":"name 既不在 GROUP BY 也非聚合函数会触发 ONLY_FULL_GROUP_BY。要么把 name 加入 GROUP BY（若按 部门+姓名 分组），要么对 name 做聚合（如 GROUP_CONCAT 拼成一行）。"},{"kind":"output","q":"读 SQL 写输出","stem":"执行下列语句后，SELECT id, val FROM t WHERE val >= 8 ORDER BY val DESC; 的输出是？ sql CREATE TABLE t (id INT, val INT); INSERT INTO t VALUES (1,10),(2,5),(3,8); SELECT id, val FROM t WHERE val >= 8 ORDER BY val D…","opts":[],"ans":"id|val 1|10 3|8","why":"val>=8 命中 (1,10) 与 (3,8)，按 val 降序为 10、8，对应 id 1、3。"},{"kind":"coding","q":"查询高薪员工","stem":"在 employee（emp_id, name, dept_id, salary）表中，写出 SQL 查询薪资大于 5000 的员工姓名与薪资，按薪资从高到低排序。","opts":[],"ans":"SELECT name, salary FROM employee WHERE salary > 5000 ORDER BY salary DESC;","why":"WHERE 单行过滤 + ORDER BY 排序；注意 salary 为数值比较，不要加引号。"},{"kind":"coding","q":"LeetCode 175 · 组合两张表（combine-two-tables）","stem":"基于 Person 与 Address 两张表，查出每个人的FirstName、LastName、City、State；没有地址的人也要出现（地址字段为 NULL）。用 LEFT JOIN 实现。","opts":[],"ans":"SELECT p.FirstName, p.LastName, a.City, a.State FROM Person p LEFT JOIN Address a ON p.PersonId = a.PersonId;","why":"题目要求即使没有地址也要保留人员，因此必须以 Person 为左表做 LEFT JOIN；这是联结语义的经典题。"}],"works":[{"h":"UPDATE/DELETE 忘写 WHERE","d":"UPDATE employee SET salary=0; 会清空整张表薪资。正确写法：先 SELECT 确认影响集，再补 WHERE emp_id=...；生产建议开启 SQL_SAFE_UPDATES。"},{"h":"SELECT 非聚合列未进 GROUP BY","d":"SELECT dept_id, name FROM employee GROUP BY dept_id; 中 name 既不在 GROUP BY 也非聚合函数，在标准 ONLY_FULL_GROUP_BY 模式下直接报错（MySQL 5.7+ 默认开启）。正确写法：把 name 加入 GROUP BY，或对 name 使用 MAX()…"},{"h":"用 WHERE 过滤聚合结果","d":"... WHERE AVG(salary)>7000 GROUP BY dept_id 非法，聚合值不能在 WHERE 中过滤。正确写法：改用 HAVING AVG(salary) > 7000。"},{"h":"混淆 INNER JOIN 与 LEFT JOIN 的 NULL 语义","d":"LEFT JOIN 右表无匹配时列值为 NULL，若再用 WHERE right.col = 'x' 过滤会把 NULL 行一并剔掉，等价于 INNER JOIN。正确写法：把右表过滤条件放进 ON（如 ON e.dept_id=d.dept_id AND d.location='Beijing'），或显式 WHERE right.c…"},{"h":"字符串比较用单引号、列名别用关键字","d":"MySQL 字符串字面量用单引号 'Alice'；双引号在 ANSI 模式下会被当作标识符。列名若用了 order/group 等保留字需用反引号 order 包裹，否则报语法错。"},{"h":"LIMIT 不分页时会拿到不稳定顺序","d":"未加 ORDER BY 的 LIMIT 3 返回的是「存储引擎任意 3 行」，多次执行顺序可能不同。正确写法：始终配合确定性的 ORDER BY 主键/唯一列。"},{"h":"NOT IN 遇到 NULL 返回空集","d":"x NOT IN (…, NULL) 恒为 UNKNOWN，WHERE 丢弃 UNKNOWN，于是整条查询返回空。用 NOT EXISTS 替代，或确保子查询结果非空（WHERE col IS NOT NULL）。"},{"h":"COUNT(col) 与 COUNT() 口径混用","d":"列可为 NULL 时前者会少数；统计\"人数\"却用了 COUNT(email)，结果偏小。按业务语义选，别按习惯选。"}],"asks":[{"q":"WHERE 和 HAVING 都能过滤，什么时候必须用 HAVING？","a":"WHERE 在分组前过滤行，不能使用聚合函数；HAVING 在分组后过滤组，可以使用聚合函数（如 COUNT()、AVG()）。 所以「按部门统计人数，只保留人数 ≥2 的部门」必须写 GROUP BY dept HAVING COUNT() >= 2，不能写成 WHERE COUNT() >= 2。 性能提示：能提前在 WHERE 中过滤的条件不要放到 HAVING——越早减少行数，分组代价越低…","fu":["SQL 的执行顺序是怎样的？","为什么 SELECT dept, COUNT() FROM emp WHERE salary > 5000 GROUP…"],"tag":"通用"},{"q":"一张 500 万行的表，某个查询很慢，你会如何排查？","a":"1. 定位慢 SQL：开启慢查询日志（slow_query_log、long_query_time），用 mysqldumpslow / pt-query-digest 聚合分析 Top N。 2. 看执行计划：EXPLAIN 关注 type（尽量避免 ALL 全表扫）、key（是否用到预期索引）、rows（预估扫描行数）、Extra（Using filesort/Using temporary…","fu":["EXPLAIN 中 type=ALL 一定意味着要加索引吗？","为什么有时加了索引优化器却不用？"],"tag":"通用/阿里"},{"q":"事务的隔离级别有哪些？InnoDB 默认哪个，如何解决幻读？","a":"四种隔离级别（由低到高）： | 级别 | 脏读 | 不可重复读 | 幻读 | |---|---|---|---| | 读未提交 RU | 有 | 有 | 有 | | 读已提交 RC | 无 | 有 | 有 | | 可重复读 RR（InnoDB 默认） | 无 | 无 | 基本无 | | 串行化 Serializable | 无 | 无 | 无 | - 脏读：读到别人未提交的数据。 - 不可重复读：…","fu":["MVCC 中 RC 和 RR 生成 ReadView 的时机有何不同？","什么是当前读和快照读？"],"tag":"通用/腾讯"}]},{"id":"db-ch02","subj":"database","title":"表连接与子查询：JOIN、子查询、集合操作","summary":"JOIN 执行算法（Nested Loop / Block Nested Loop / Hash Join / Merge Join）与驱动表选择；INNER/LEFT/RIGHT/CROSS/SELF JOIN 与 NULL 语义；子查询…","concepts":[{"id":"db-ch02/01-join-algorithms","file":"01-join-algorithms.md","title":"01 · JOIN 的执行算法：从\"双重循环\"到 Hash/Merge Join","kind":"flow","secs":[{"h":"1. 理论根基：JOIN 是两个关系的「笛卡尔积 + 选择」","s":"关系代数里，R ⋈ S 的严格定义是 σ_cond(R × S)：先对两表做笛卡尔积（行数 = |R|×|S|），再用连接条件做选择。朴素实现是 O(|R|·|S|)，对两张大表不可接受。所有 JOIN 算法都是在\"避免物化完整笛卡尔积…","c":null},{"h":"2. 实现机制：InnoDB/优化器怎么选","s":"MySQL 优化器在 8.0 之前主要靠「索引嵌套循环」（Index Nested Loop Join，NLJ 的升级版：驱动表出一行，用连接键走内表索引，复杂度 O(M·log N)）。8.0.18 起引入 Hash Join，用于「…","c":null},{"h":"3. 工程实践与权衡","s":"","c":null},{"h":"4. 边界与陷阱","s":"","c":null},{"h":"5. 可运行代码","s":"见 examples/ex01-inner-join-dept.json（INNER JOIN）、examples/ex02-left-join-null.json（NULL 语义）、examples/ex03-block-nested…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"sql","code":"CREATE TABLE department (dept_id INT PRIMARY KEY, dept_name VARCHAR(20), location VARCHAR(20));\nCREATE TABLE employee (emp_id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, salary DECIMAL(10,2));\nINSERT INTO department VALUES (10,'Sales','Beijing'),(20,'Engineering','Shanghai'),(30,'HR','Shenzhen');\nINSERT INTO employee VALUES (1,'Alice',10,6000.00),(2,'Bob',20,8000.00),(3,'Carol',10,4500.00),(4,'Dave',20,9000.00),(5,'Eve',30,5000.00),(6,'Frank',20,7000.0\n…"}}]},{"id":"db-ch02/02-subquery","file":"02-subquery.md","title":"02 · 子查询：分类、相关 vs 非相关，与 MySQL 的优化","kind":"compare","secs":[{"h":"1. 理论根基：子查询的四种形态","s":"","c":null},{"h":"2. 实现机制：MySQL 如何\"拆掉\"子查询","s":"现代优化器会尽量避免\"逐行执行相关子查询\"，手段：","c":null},{"h":"3. IN vs EXISTS：别再背\"小表用 IN、大表用 EXISTS\"","s":"老经验说\"外表大用 EXISTS、内表大用 IN\"，但在 MySQL 5.6+ 有 semi-join 优化后，优化器会把两者都转成等价的 semi-join 执行，性能差异通常可忽略。真正要警惕的是：","c":null},{"h":"4. 工程实践","s":"","c":null},{"h":"5. 可运行代码","s":"见 examples/ex04-scalar-subquery.json（标量子查询）、examples/ex05-in-subquery.json（IN 子查询 + semi-join）、examples/ex06-exists-an…","c":null}]},{"id":"db-ch02/03-set-operations","file":"03-set-operations.md","title":"03 · 集合操作：UNION / INTERSECT / EXCEPT","kind":"flow","secs":[{"h":"1. 理论根基：多重集（Multiset）语义","s":"SQL 表是多重集（允许重复行），集合操作默认带 DISTINCT 去重：","c":null},{"h":"2. 实现机制：去重为什么慢","s":"UNION（带去重）的实现是：把两结果集合并后做一次 filesort（或哈希去重），复杂度 O((m+n) log(m+n))。UNION ALL 只是把两游标顺序输出，O(m+n)，无排序、无临时表。","c":null},{"h":"3. 等价改写（程序员必会）","s":"注意：UNION 要求列数相同、对应列类型兼容；结果列名取第一个 SELECT 的列名。","c":null},{"h":"4. 工程实践与坑","s":"","c":null},{"h":"5. 可运行代码","s":"见 examples/ex09-union-all.json、examples/ex10-union-dedup.json、examples/ex12-intersect-except.json（演示 8.0.31+ 原生写法与低版本…","c":null}]},{"id":"db-ch02/04-denormalization","file":"04-denormalization.md","title":"04 · 范式与反范式：理论正确性与工程代价的权衡","kind":"flow","secs":[{"h":"1. 理论根基：范式是不让数据\"说假话\"的规则","s":"范式建立在函数依赖（FD）：X → Y 之上——若 X 相同则 Y 必相同。","c":null},{"h":"2. 实现机制：反范式的本质是\"用空间换 JOIN 的时间\"","s":"严格遵守 3NF 的代价是查询要大量 JOIN（emp ⋈ dept ⋈ loc ...），而 JOIN 在大表上是昂贵操作（见 concept 01）。因此工程上常有意违反范式——反范式（Denormalization）：","c":null},{"h":"3. 工程实践：何时反范式","s":"","c":null},{"h":"4. 边界与陷阱","s":"","c":null},{"h":"5. 可运行代码","s":"见 examples/ex11-self-join.json 中\"冗余部门名省去 JOIN\"的对比思路，以及 examples/ex12-intersect-except.json 用集合操作表达\"既要 A 又要 B\"的报表语义。","c":null}]},{"id":"db-ch02/05-sql-practical-recipes","file":"05-sql-practical-recipes.md","title":"凯喵实战手记：SQL 连接与子查询——写对结果却跑死的那些现场","kind":"flow","secs":[{"h":"1. INNER JOIN 只留两表都匹配的行","s":"凯喵第一次 join 用户和订单，发现「没下过单的用户全没了」：","c":{"lang":"sql","code":"SELECT u.name, o.amount\nFROM users u\nJOIN orders o ON u.id = o.user_id;   -- 只返回有订单的用户"}},{"h":"2. LEFT JOIN 之后 WHERE 过滤右表会退化成内连接","s":"凯喵想查「所有用户及其已支付订单」，结果左表被悄悄砍掉：","c":{"lang":"sql","code":"SELECT u.name, o.amount\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nWHERE o.status = 'paid';   -- 右表没匹配的 o.status 为 NULL，被 WHERE 滤掉！"}},{"h":"3. 笛卡尔积：忘了 ON 条件的灾难","s":"凯喵漏写 join 条件，结果行数爆炸：","c":{"lang":"sql","code":"SELECT * FROM users, orders;          -- 没有 ON：N×M 行，灾难\nSELECT * FROM users CROSS JOIN orders; -- 明确要笛卡尔积才这么写"}},{"h":"4. 自连接：同一张表当两张用","s":"凯喵查「每个员工的经理姓名」，一张员工表搞定：","c":{"lang":"sql","code":"SELECT e.name, m.name AS manager\nFROM emp e\nLEFT JOIN emp m ON e.manager_id = m.id;"}},{"h":"5. 子查询相关与不相关：性能天差地别","s":"凯喵写的相关子查询慢到超时：","c":{"lang":"sql","code":"-- 相关子查询：外层每行都重跑一次内层\nSELECT name FROM emp e\nWHERE salary > (SELECT AVG(salary) FROM emp WHERE dept = e.dept);\n\n-- 改写成 JOIN + 聚合，通常快得多\nSELECT e.name\nFROM emp e JOIN (SELECT dept, AVG(salary) a FROM emp GROUP BY dept) d\n  ON e.dept = d.dept AND e.salary > d.a;"}},{"h":"6. EXISTS vs IN：NULL 语义与空值处理","s":"凯喵在「有订单的用户」上纠结用哪个：","c":{"lang":"sql","code":"SELECT name FROM users u\nWHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);\n-- 比 IN (SELECT user_id ...) 在 user_id 有 NULL 时更安全，且常更快"}},{"h":"7. 集合运算：UNION 去重 vs UNION ALL","s":"凯喵用 UNION 合并日志，慢了一倍还丢了重复：","c":{"lang":"sql","code":"SELECT col FROM t1\nUNION ALL          -- 保留全部行，不去重，快\nSELECT col FROM t2;\n-- UNION 会去重（隐式 DISTINCT），若不需要去重请用 UNION ALL"}},{"h":"8. INTERSECT / EXCEPT：交集与差集","s":"凯喵查「A 表有但 B 表没有的 ID」用了 NOT IN，被 NULL 坑：","c":{"lang":"sql","code":"-- 更稳的写法：EXCEPT（差集）\nSELECT id FROM a\nEXCEPT\nSELECT id FROM b;"}},{"h":"9. 反范式：用冗余换读性能","s":"凯喵的订单列表每次都要 JOIN 用户表取昵称，QPS 上不去：","c":{"lang":"sql","code":"-- 反范式：订单表冗余 user_name，读时不再 JOIN\nALTER TABLE orders ADD COLUMN user_name VARCHAR(64);\n-- 写时双写/通过触发器同步，读时单表查询"}},{"h":"10. 用窗口函数做「每组 Top-N」","s":"凯喵想取每个部门工资最高的两人，GROUP BY 做不到：","c":{"lang":"sql","code":"SELECT name, dept, salary FROM (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) rn\n  FROM emp\n) t WHERE rn <= 2;"}},{"h":"11. 聚合陷阱：SELECT 里出现非聚合非分组列","s":"凯喵写出语义错误的聚合查询：","c":{"lang":"sql","code":"SELECT dept, name, MAX(salary)   -- name 既不是分组列也不是聚合，结果无意义\nFROM emp GROUP BY dept;"}},{"h":"12. 执行顺序：写的是 SELECT-FROM-WHERE，跑的是 FROM-WHERE-…","s":"凯喵总搞不清别名在哪能用：","c":{"lang":"sql","code":"-- 逻辑执行顺序：FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY\nSELECT dept AS d, COUNT(*) c\nFROM emp\nWHERE salary > 1000        -- WHERE 在 SELECT 前，不能用 c 或 d 别名\nGROUP BY d                  -- GROUP BY 多数库能用 SELECT 别名，但不完全通用\nORDER BY c DESC;            -- ORDER BY 在最后，能用别名"}},{"h":"凯喵复盘：SQL 的两个灵魂问题","s":"这 12 个现场都绕不开两个灵魂问题：语义上「我要的是哪种集合运算」，性能上「引擎会怎么跑」。LEFT JOIN 退化成内连接、UNION 偷偷去重、IN 遇 NULL 翻车，都是「集合语义理解错」；相关子查询慢、意外笛卡尔积、GROU…","c":null},{"h":"🧑‍💻 程序员视角","s":"LEFT JOIN 之后在 WHERE 里过滤右表字段，会把「左表全保留」的语义破坏成 INNER JOIN——右表为 NULL 的行被过滤掉了，条件必须写在 ON 里。忘了 ON 条件会产生笛卡尔积，两张十万行的表直接生成百亿行。自连…","c":null},{"h":"🎓 博士生视角","s":"SQL 的执行语义是「先 FROM/JOIN 构造笛卡尔积 → 再 WHERE 过滤 → 再 GROUP BY → 再 HAVING → 再 SELECT → 最后 ORDER BY/LIMIT」，理解这个顺序才能解释「为什么 WHER…","c":null},{"h":"📚 考研者视角","s":"数据库面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 JOIN 执行算法，下列说法正确的是","stem":"给定两表 A（10 万行，无连接索引）与 B（100 行，连接列有索引），以下说法哪项正确？","opts":[{"k":"A","t":"Hash Join 只能用于非等值连接（如 a.x < b.y）"},{"k":"B","t":"Nested Loop Join 对外表每行都去内表逐行比对，复杂度约 O(|A|·|B|)；若内表连接列有索引，Ind…"},{"k":"C","t":"Block Nested Loop Join 是把整张内表常驻内存，永远比 Hash Join 快"},{"k":"D","t":"无论数据量如何，MySQL 永远优先选择 Merge Join"}],"ans":"B","why":"Hash Join 仅支持等值连接（A 错）；BNL 是把驱动表一批行放进 join buffer 批量探测内表，减少的是对内表的扫描轮数，并非永远快于 Hash Join（C 错）；优化器按代价选型，并非永远 Merge Join（D 错）。Index Nested Loop（内表走索引）是 O(|A|·log|B|)，是带索引 NLJ 的准确复杂度（B 对）。"},{"kind":"output","q":"读 LEFT JOIN 写输出","stem":"执行下列语句后，SELECT c.cust_name, o.amount FROM customer c LEFT JOIN orders o ON c.cust_id=o.cust_id ORDER BY c.cust_id; 的输出是？ sql CREATE TABLE customer (cust_id INT PRIMARY KEY, cust_name VARCHAR(20)); CRE…","opts":[],"ans":"cust_name|amount Tom|200.00 Tom|350.00 Jerry|NULL Lucy|NULL","why":"Tom 有 2 笔订单故两行；Jerry、Lucy 在 orders 中无匹配，左连接保留左表行、右表列补 NULL。"},{"kind":"fix_error","q":"修复 NOT IN 的 NULL 陷阱","stem":"目标是查出「没有下过任何订单」的客户，但下面语句在有 NULL 订单金额时会返回空集，请修复： sql SELECT cust_name FROM customer WHERE cust_id NOT IN (SELECT cust_id FROM orders); （orders.cust_id 可能为 NULL）","opts":[],"ans":"SELECT cust_name FROM customer c WHERE NOT EXISTS ( SELECT 1 FROM orders o WHERE o.cust_id = c.cust_id );","why":"当子查询含 NULL 时，NOT IN (..., NULL) 整体结果为 UNKNOWN，导致 0 行。改用 NOT EXISTS 只对“是否存在匹配行”求值，NULL 行只是不匹配，不受影响；等价写法还有 LEFT JOIN orders ON ... WHERE orders.cust_id IS NULL。"},{"kind":"coding","q":"把相关子查询改写为 JOIN 聚合","stem":"下列查询对每个客户执行一次子查询（N+1），在客户量大时很慢，请改写成一次 LEFT JOIN + GROUP BY 的等价写法，输出客户名与订单数（无订单显示 0）： sql SELECT c.cust_name, (SELECT COUNT() FROM orders o WHERE o.cust_id = c.cust_id) AS cnt FROM customer c;","opts":[],"ans":"SELECT c.cust_name, COUNT(o.order_id) AS cnt FROM customer c LEFT JOIN orders o ON o.cust_id = c.cust_id GROUP BY c.cust_id, c.cust_name ORDER BY c.cust_id;","why":"把“逐行子查询计数”改成一次关联后按客户分组计数；LEFT JOIN 保证无订单客户也出现，COUNT(o.order_id) 对 NULL 计 0。"},{"kind":"coding","q":"LeetCode 184 · 部门最高薪资（department-highest-salary）","stem":"查出每个部门里薪资最高的员工（可能有并列第一）。需要同时返回部门名。提示：可用 INNER JOIN + 子查询（按部门求 MAX 薪资）或窗口函数 DENSE_RANK()。","opts":[],"ans":"SELECT d.name AS Department, e.name AS Employee, e.salary AS Salary FROM employee e JOIN department d ON d.id = e.department_id WHERE (e.department_id, e.salary…","why":"用「(部门, 最高薪资)」的集合做 IN 匹配，天然支持并列第一；也可用 DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) 后取 rank=1。"},{"kind":"coding","q":"LeetCode 185 · 部门薪资前三高（department-top-three-salaries）","stem":"查出每个部门薪资排名前三高的员工（并列同名次，如 1/1/3 或 1/2/3 都算前三）。建议用窗口函数或「自连接计数法」。","opts":[],"ans":"SELECT Department, Employee, Salary FROM ( SELECT d.name AS Department, e.name AS Employee, e.salary AS Salary, DENSE_RANK() OVER (PARTITION BY e.department_id…","why":"用 DENSE_RANK 按部门分区对薪资降序排名，取 ≤3 即含并列；自连接计数法为：同一部门比自己薪资高的人数 <3 即进前三，但并列处理不如窗口函数清晰。"}],"works":[{"h":"LEFT JOIN 把右表过滤条件写进 WHERE 反而变 INNER JOIN","d":"SELECT ... FROM A LEFT JOIN B ON A.id=B.aid WHERE B.status='ok'：右表无匹配的行 B.status 为 NULL，被 WHERE 剔掉，等价 INNER JOIN。正确写法：把右表过滤放进 ON（ON A.id=B.aid AND B.status='ok'），或显式 WH…"},{"h":"NOT IN 子查询含 NULL 返回空集","d":"WHERE id NOT IN (SELECT mid FROM t WHERE mid IS NOT NULL 的补集...) 一旦子查询出现任意 NULL，整个表达式结果为 UNKNOWN，整条查询返回 0 行。正确写法：用 NOT EXISTS (SELECT 1 FROM t WHERE t.mid = a.id) 或 LEF…"},{"h":"相关子查询写在 SELECT 列表引发 N+1","d":"SELECT name, (SELECT COUNT() FROM orders o WHERE o.cid=c.id) FROM customer c 会对每个客户执行一次子查询，客户多时极慢。正确写法：改写成 LEFT JOIN + GROUP BY 一次聚合出计数。"},{"h":"盲目用 UNION 而非 UNION ALL 触发隐式排序去重","d":"两结果集确定不重叠时，UNION 仍会做一次 filesort 去重，白白浪费。正确写法：确认无重叠时用 UNION ALL；需要去重才用 UNION。"},{"h":"派生表（FROM 子查询）没加限制导致物化巨型临时表","d":"FROM (SELECT FROM huge WHERE ...) t 若子查询带 GROUP BY/DISTINCT/LIMIT 无法被合并，会物化成磁盘临时表。正确写法：只 SELECT 必要列、尽量把过滤/聚合下推到派生表内，或改写成 JOIN/视图让优化器合并。"},{"h":"多表 JOIN 连接列类型/字符集不一致导致索引失效退化 BNL","d":"a.uid(VARCHAR) JOIN b.user_id(INT) 或两边字符集（utf8 vs utf8mb4）不同，会触发隐式转换，内表索引用不上，退化成 Block Nested Loop 全表扫描。正确写法：统一连接列的类型与字符集、加索引。"},{"h":"IN 列表过长被优化器放弃","d":"col IN (上千个常量) 超过 range_optimizer_max_mem_size 会退化为全表扫描。正确写法：把列表落成临时表再 JOIN，或改用 EXISTS 子查询。"},{"h":"NOT IN 的子查询里出现 NULL，结果集直接变空","d":"WHERE id NOT IN (SELECT fk FROM t2) 只要子查询返回一个 NULL，整体就恒为空——三值逻辑下 id <> NULL 是 UNKNOWN，永远不满足 TRUE。这类 bug 表现为「数据明明存在却查不出来」。 改用 NOT EXISTS（对 NULL 安全）；或子查询里加 WHERE fk IS NO…"}],"asks":[{"q":"MySQL 的 JOIN 有哪几种执行算法？分别适合什么场景？","a":"主要有四类： 1. Index Nested Loop Join（NLJ）：驱动表每行拿连接键走内表索引，O(驱动行数·log 内表)。前提是内表连接列有索引，最常见、最理想。 2. Block Nested Loop Join（BNL）：无可用索引时的兜底，把驱动表一批行放进 join_buffer，批量探测内表，减少内表被扫描的轮数（仍 O(M·N)，但 I/O 次数大幅下降）。 3. Has…","fu":["为什么常说「小表驱动大表」？","EXPLAIN 里怎么看出用了哪种 JOIN（type / Extra: Using join buffer）？"],"tag":"通用/字节"},{"q":"IN 和 EXISTS 怎么选？NOT IN 有什么坑？","a":"现代 MySQL（5.6+ semi-join 优化）下，IN (子查询) 与 EXISTS 都会被优化器转成等价的 semi-join 执行，性能差异通常可忽略，不必死记「大表用 EXISTS」。 - 真正的坑在 NOT IN：若子查询返回集合里含 NULL，WHERE col NOT IN (..., NULL) 整体结果为 UNKNOWN，查询返回空集。而 NOT EXISTS / LEFT…","fu":["semi-join 有哪几种策略（FirstMatch / MaterializedLookup ...）？","为什么 NOT IN 遇到 NULL 会变 UNKNOWN？"],"tag":"通用/阿里"},{"q":"一个千万行的订单表 JOIN 用户表很慢，你怎么排查和优化？","a":"1. 看执行计划：EXPLAIN 找 type: ALL + Extra: Using join buffer (Block Nested Loop) —— 说明连接列没索引，退化成 BNL。 2. 建索引：在「被驱动表」的连接列（如 orders.user_id）建索引，让优化器走 Index NLJ，复杂度从 O(M·N) 降到 O(M·log N)。 3. 统一类型/字符集：连接列两边类型…","fu":["join_buffer_size 调大一定能加速 BNL 吗？","如果连接列是低基数列（如性别），建索引还有用吗？"],"tag":"通用/腾讯"}]},{"id":"db-ch03","subj":"database","title":"索引与事务：B+树索引、ACID、隔离级别","summary":"InnoDB B+树索引结构（聚簇/二级索引、页 16KB、树高、根到叶查询路径、页分裂与合并）；回表与覆盖索引、最左前缀原则、索引下推 ICP；事务 ACID（redo log / undo log / double write buff…","concepts":[{"id":"db-ch03/01-bplus-tree-index","file":"01-bplus-tree-index.md","title":"01 · InnoDB B+树索引的物理结构","kind":"flow","secs":[{"h":"1. 理论根基：为什么是 B+树，不是哈希/红黑树/B树","s":"索引的本质是\"用额外的空间换查找的 I/O 次数\"。候选结构对比：","c":null},{"h":"2. 实现机制：InnoDB 的页与两类索引","s":"InnoDB 按 页（默认 16KB） 组织磁盘，B+树的一个节点 = 一个页。","c":null},{"h":"3. 工程实践","s":"","c":null},{"h":"4. 边界与陷阱","s":"","c":null},{"h":"5. 可运行代码","s":"见 examples/ex01-create-and-explain-index.json（建索引+EXPLAIN 看走索引）、examples/ex12-show-index-metadata.json（SHOW INDEX 看索引列…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"sql","code":"CREATE TABLE emp (emp_id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, salary DECIMAL(10,2));\nINSERT INTO emp VALUES (1,'Alice',10,6000.00),(2,'Bob',20,8000.00),(3,'Carol',10,4500.00),(4,'Dave',20,9000.00),(5,'Eve',30,5000.00),(6,'Frank',20,7000.00);\nCREATE INDEX idx_dept ON emp(dept_id);\nEXPLAIN SELECT * FROM emp WHERE dept_id = 20;"}}]},{"id":"db-ch03/02-covering-index-leftmost","file":"02-covering-index-leftmost.md","title":"02 · 回表、覆盖索引与最左前缀原则","kind":"flow","secs":[{"h":"1. 回表（Bookmark Lookup）：二级索引的隐含成本","s":"二级索引叶子只存 (索引列, 主键值)。当查询还需要其它列时，InnoDB 用拿到的主键回聚簇索引再查一次取完整行。回表次数 = 二级索引命中的行数。命中 1 行回表 1 次；命中 10 万行就回表 10 万次——这就是为什么\"大结果集…","c":null},{"h":"2. 覆盖索引（Covering Index）：避免回表","s":"若索引本身包含查询所需的全部列（包括 SELECT 列与 WHERE 列），引擎在二级索引叶子就能拿到一切，无需回表。EXPLAIN 的 Extra 出现 Using index 即表示覆盖索引生效。","c":null},{"h":"3. 最左前缀原则（Leftmost Prefix）","s":"联合索引 (a, b, c) 相当于建了 (a)、(a,b)、(a,b,c) 三套前缀。查询必须从最左列开始才能利用索引：","c":null},{"h":"4. 索引下推 ICP（Index Condition Pushdown，5.6+）","s":"没有 ICP 时，存储引擎按索引把 a=1 AND b>10 命中的行全部回表交给 Server 层，Server 再判断 c=5。","c":null},{"h":"5. 工程实践与坑","s":"","c":null},{"h":"6. 可运行代码","s":"见 examples/ex02-covering-index.json（覆盖索引 Using index）、examples/ex03-back-to-table.json（SELECT 回表对比）、examples/ex04-left…","c":null}]},{"id":"db-ch03/03-acid-isolation-mvcc","file":"03-acid-isolation-mvcc.md","title":"03 · 事务 ACID、隔离级别与 MVCC","kind":"timeline","secs":[{"h":"1. ACID 的落地机制（一句话版）","s":"","c":null},{"h":"2. 三大读问题与四种隔离级别","s":"","c":null},{"h":"3. MVCC：多版本并发控制（核心）","s":"每行 InnoDB 记录有隐藏列：DB_TRX_ID（最后修改它的事务 ID）、DB_ROLL_PTR（回滚指针，指向 undo log 中该行的上一个版本）。每次更新都不原地覆盖，而是写新版本、旧版本挂到 undo 链上。","c":null},{"h":"4. 当前读 vs 快照读","s":"","c":null},{"h":"5. 工程实践","s":"","c":null},{"h":"6. 可运行代码","s":"见 examples/ex07-transaction-rollback.json（原子性：回滚）、examples/ex08-mvcc-repeatable-read.json（RR 快照读一致）、examples/ex09-curr…","c":null}]},{"id":"db-ch03/04-redo-undo-lock","file":"04-redo-undo-lock.md","title":"04 · redo/undo log 与锁（Next-Key Lock、死锁、长事务）","kind":"flow","secs":[{"h":"1. redo log：崩溃恢复与 WAL","s":"","c":null},{"h":"2. double write buffer：防\"页断裂\"","s":"InnoDB 页 16KB，但磁盘扇区常 512B/4KB，一次写页可能只写入一半就断电 → 页损坏、redo 也无力（redo 基于\"整页\"重放）。double write buffer 先顺序写一份页副本，再写真正位置；崩溃时若真页…","c":null},{"h":"3. undo log：回滚 + MVCC 的版本源","s":"","c":null},{"h":"4. 锁：行锁、间隙锁、Next-Key Lock（解决幻读）","s":"InnoDB 锁加在索引记录上（没索引会锁全表！）。","c":null},{"h":"5. 死锁与长事务","s":"","c":null},{"h":"6. 工程实践","s":"","c":null},{"h":"7. 可运行代码","s":"见 examples/ex07-transaction-rollback.json（undo 回滚）、examples/ex11-redo-undo-vars.json（redo/undo 相关系统变量）、examples/ex09-c…","c":null}]},{"id":"db-ch03/05-index-transaction-practical-recipes","file":"05-index-transaction-practical-recipes.md","title":"索引与事务实战手记：凯喵从一条慢查询查到 MVCC 的十二个现场","kind":"flow","secs":[{"h":"开场：慢查询的归因顺序","s":"凯喵的固定流程是四步，从不跳步：","c":{"lang":"sql","code":"EXPLAIN SELECT * FROM orders WHERE user_id = 10086;\n-- type: ALL, rows: 1200000, Extra: Using where"}},{"h":"收尾：凯喵的索引与事务排查口诀","s":"五句话应付大部分情况：","c":null}]}],"exams":[{"kind":"choice","q":"关于 InnoDB B+树索引，下列说法正确的是","stem":"下列说法哪项正确？","opts":[{"k":"A","t":"B+树的非叶子节点也存储完整行数据，因此查询更快"},{"k":"B","t":"哈希索引支持高效的范围查询（如 salary > 5000）"},{"k":"C","t":"B+树非叶子节点只存键+指针，扇出大、树高低；叶子节点存数据且用双向链表串联，范围查询只需顺链表扫描"},{"k":"D","t":"聚簇索引的叶子节点存的是主键值，必须再回表才能拿到整行"}],"ans":"C","why":"B+树非叶子节点不存行（A 错）；哈希索引不支持范围（B 错）；聚簇索引叶子存的就是整行，无需回表（D 错）。C 准确描述了 B+树扇出大、范围查询沿叶子链表走的优势。"},{"kind":"choice","q":"联合索引 (a,b,c) 的最左前缀应用","stem":"已知联合索引 idx(a,b,c)，下列哪些查询能充分利用到该索引对 c 列的定位（即不止用 a）？","opts":[{"k":"A","t":"WHERE a=1 AND b=2 AND c=3"},{"k":"B","t":"WHERE a=1 AND c=3"},{"k":"C","t":"WHERE b=2 AND c=3"},{"k":"D","t":"WHERE a=1 AND b>2 AND c=3"}],"ans":"A","why":"最左前缀要求从 a 开始连续：A 三列都等值可用；B 只有 a 用得上、c 不能定位；C 缺 a 完全用不上；D 中 b 是范围，会截断后续列，c 无法用于索引定位（只能靠 ICP 过滤）。所以只有 A 充分利用到 c。"},{"kind":"fix_error","q":"修复对索引列套函数导致的索引失效","stem":"create_time 上有索引，但下面查询走全表扫描，请修复： sql SELECT FROM orders WHERE DATE(create_time) = '2023-01-01';","opts":[],"ans":"SELECT FROM orders WHERE create_time >= '2023-01-01' AND create_time < '2023-01-02';","why":"DATE(create_time) 对列套了函数，等价于隐式计算，索引无法用于范围定位。改成范围区间后，优化器能用索引做 range 扫描，命中 2023-01-01 全天。"},{"kind":"coding","q":"设计覆盖索引","stem":"高频查询：SELECT user_id, status, created_at FROM orders WHERE user_id = ? AND status = ? ORDER BY created_at LIMIT 20;。请设计一条联合索引，使该查询既走索引、又避免回表、且排序免 filesort。","opts":[],"ans":"ALTER TABLE orders ADD INDEX idx_user_status_ct (user_id, status, created_at);","why":"(user_id, status) 等值过滤、created_at 放最后既可用于 ORDER BY（避免 filesort）又使三列都在索引内 → 覆盖索引（Extra: Using index），无需回表。列序遵循'等值在前、范围/排序在后'。"},{"kind":"coding","q":"LeetCode 178 · 分数排名（rank-scores）","stem":"给分数表排并列名次：相同分数同名次，且后续名次跳过（如 100,100,90 → 1,1,3）。可用窗口函数 DENSE_RANK() 或自连接计数法。","opts":[],"ans":"SELECT score, DENSE_RANK() OVER (ORDER BY score DESC) AS rank FROM scores ORDER BY score DESC;","why":"DENSE_RANK 对相同分数给相同名次且连续不跳号，正好匹配'并列且后续名次跳过'的语义；自连接计数法为：比自己分数高或相等的去重计数 = 名次。"},{"kind":"coding","q":"LeetCode 196 · 删除重复邮箱（delete-duplicate-emails）","stem":"保留每个邮箱对应 id 最小的记录，删除其余重复行。建议用自连接定位需删除的行或子查询取每组最小 id。","opts":[],"ans":"DELETE p1 FROM person p1 JOIN person p2 ON p1.email = p2.email AND p1.id > p2.id;","why":"自连接把同一 email 且 id 更大 的行配对，删除这些较大 id 的重复行，仅保留每组最小 id；也可用 DELETE FROM person WHERE id NOT IN (SELECT MIN(id) ... GROUP BY email)（注意 MySQL 不允许同表子查询直接删，需套一层派生表）。"},{"kind":"output","q":"手算三层 B+ 树能索引多少行","stem":"InnoDB 页大小 16KB = 16384B。主键 BIGINT 占 8B，页指针占 6B，每页有 6B 页头开销。非叶节点每条索引项 = 主键 + 页指针；叶子节点同样按「主键 + 行指针」计算容量（简化模型）。 求：一个三层（根 → 中间层 → 叶）的 B+ 树最多能索引多少行？给出精确整数。","opts":[],"ans":"1597509809","why":"每页 1169 项，三层容量 1169³ ≈ 16 亿行。"}],"works":[{"h":"SELECT + 二级索引必然回表，大结果集时优化器会放弃索引","d":"查询只需要少数列时却写 SELECT ，二级索引无法覆盖，每行都要回表；命中行数多时回表成本超过全表扫描，优化器反而选 ALL。正确写法：只查需要的列，或建覆盖索引（Extra: Using index）避免回表。"},{"h":"违反最左前缀：跳列 / 前导通配 / 对列套函数，索引直接失效","d":"联合索引 (a,b,c)，写 WHERE b=2、WHERE name LIKE '%明'、WHERE YEAR(created_at)=2023 都让索引用不上（退化为全表扫）。正确写法：等值列放最左、范围列放中、用 created_at BETWEEN ... AND ... 替代函数包裹、前缀匹配才用 LIKE '明%'。"},{"h":"隐式类型转换导致索引失效","d":"phone 是 VARCHAR，却写 WHERE phone=13800138000（数字），MySQL 会对 phone 做隐式 CAST，等价于对列套函数 → 索引失效、全表扫。正确写法：WHERE phone='13800138000'（字符串加引号），并保证连接/比较两边类型一致。"},{"h":"误以为 RR 完全无幻读：当前读仍可能看到\"新插入行\"","d":"RR 下普通 SELECT 走快照读，看不到别的事务插入（似乎无幻读）；但 SELECT ... FOR UPDATE / UPDATE 是当前读，会看到已提交的新行。解决幻读靠 Next-Key Lock（锁住间隙阻止插入）；不要误以为 RR 下 FOR UPDATE 范围查询不会\"多出版本\"。"},{"h":"长事务：持有 ReadView 不释放，undo 版本无法 purge","d":"一个开着不提交的事务会让 MVCC 版本链无限堆积，回滚段膨胀、所有快照读变慢，还长期占锁易死锁。正确写法：事务尽量短、autocommit=1 默认开启；批量任务分批提交。"},{"h":"UPDATE/DELETE 没走索引 → 行锁升级为全表锁","d":"InnoDB 锁加在索引记录上，若 WHERE 条件列无索引，会锁住全表（或退化为逐行锁全表），瞬间卡死并发。正确写法：务必在 WHERE 列上建索引再改。"},{"h":"FOR UPDATE 范围查询会锁间隙，别在事务里长时间持有","d":"SELECT ... FOR UPDATE WHERE id BETWEEN 10 AND 20 加 Next-Key Lock，锁住 (10,20) 间隙，别的事务插入该区间会阻塞甚至死锁。正确写法：锁粒度尽量小、锁完立即处理并尽快提交。"},{"h":"在索引列上套函数或隐式类型转换 → 索引失效","d":"WHERE DATE(created_at) = '2026-10-31'、WHERE varchar_col = 123（字符串列与数字比较会隐式转换）都会让 B+ 树无法按序定位，退化成全表扫。EXPLAIN 里表现为 type=ALL 或 key=NULL。 改写成范围：created_at >= '2026-10-31' AN…"}],"asks":[{"q":"为什么 MySQL InnoDB 用 B+树而不是哈希表或红黑树做索引？","a":"三个核心原因： 1. 范围/排序友好：B+树叶子节点用双向链表串联，范围查询（a BETWEEN 1 AND 100、ORDER BY）只需顺链表扫描；哈希表完全不支持范围，红黑树中序遍历也要反复跨节点。 2. 扇出大、树高低：B+树非叶子节点只存键+指针不存行，单页（16KB）能放约上千个指针，树高通常仅 3~4 层——千万/亿级数据查询也只要 3~4 次磁盘 I/O。红黑树/二叉树节点小、树高…","fu":["聚簇索引和二级索引的叶子节点分别存什么？","为什么主键推荐自增整型而不是 UUID？"],"tag":"通用/阿里"},{"q":"MVCC 是怎么实现的？RC 和 RR 生成 ReadView 的时机有什么不同？","a":"实现：每行有隐藏列 DB_TRX_ID（最后修改事务 ID）与 DB_ROLL_PTR（指向 undo log 中旧版本的指针）。更新不原地覆盖，而是写新版本、旧版挂到 undo 链。事务做快照读时生成 ReadView（记录当前活跃未提交事务 ID 列表），沿版本链找'已提交且不在活跃列表'的第一个可见版本——读写互不阻塞。 RC vs RR 的 ReadView 时机： - RC（读已提交）：…","fu":["什么是当前读和快照读？","undo log 除了回滚还干什么？为什么长事务会让它膨胀？"],"tag":"通用/腾讯"},{"q":"最左前缀原则是什么？什么时候索引会失效？","a":"最左前缀：联合索引 (a,b,c) 必须从最左列连续使用才能走索引。WHERE a=1 AND b=2 用 (a,b)；WHERE b=2 或 WHERE a=1 AND c=3 用不上 c 的定位；WHERE a=1 AND b>2 AND c=3 因 b 是范围，截断后续列，c 只能靠 ICP 过滤。 常见失效场景： 1. 不按最左列开头（跳列、缺最左列）； 2. 对索引列做函数/运算（DAT…","fu":["什么是索引下推 ICP？它怎么补救范围截断？","什么情况下优化器宁可全表扫描也不用二级索引？"],"tag":"通用/拼多多"}]},{"id":"db-ch04","subj":"database","title":"查询优化与执行计划（EXPLAIN）","summary":"EXPLAIN 输出解读（type/key/rows/Extra）；索引失效场景；覆盖扫描与文件排序；慢查询日志与 profiling；执行计划优化思路。","concepts":[{"id":"db-ch04/01-explain-columns-and-type-ladder","file":"01-explain-columns-and-type-ladder.md","title":"01 · EXPLAIN 输出解读：type、key、rows 与 Extra","kind":"flow","secs":[{"h":"一、EXPLAIN 的每一列在说什么","s":"varchar(n) = 4n + 2（可变长 + 长度前缀）；char(n) = 4n；","c":{"lang":"text","code":"+----+-------------+-------+------+---------------+---------+---------+-------+------+-----------------------+\n| id | select_type | table | type | possible_keys | key     | key_len | ref   | rows | Extra                 |\n+----+-------------+-------+------+---------------+---------+---------+-------+------+-----------------------+\n|  1 | SIMPLE      | o     | ref  | idx_user_id   | idx_uid | 8       | const |   12 | Using index condition |\n+----+----------\n…"}},{"h":"二、type 的优劣阶梯（面试必背）","s":"出现 index 或 ALL 且 rows 很大时，就是优化目标。","c":{"lang":"text","code":"system > const > eq_ref > ref > fulltext > ref_or_null > index_merge\n       > unique_subquery > index_subquery > range > index > ALL"}},{"h":"三、Extra 的关键信号","s":"","c":null},{"h":"四、rows 与 filtered 是「估算」，不是事实","s":"优化器靠统计信息（索引基数 cardinality、数据分布直方图）估算代价。","c":null},{"h":"五、更细的观察手段","s":"EXPLAIN ANALYZE 的价值在于对照：把「估算 rows」与「实际 rows」并排看，","c":{"lang":"sql","code":"EXPLAIN FORMAT=JSON SELECT ...;          -- 结构化输出，含 cost_info\nEXPLAIN ANALYZE SELECT ...;              -- 8.0.18+，实际执行并给出真实耗时与行数\nEXPLAIN FOR CONNECTION <id>;             -- 看正在运行的连接的执行计划\nSHOW STATUS LIKE 'Last_query_cost';      -- 上一条查询的估算代价"}}]},{"id":"db-ch04/02-index-failure-and-cost-model","file":"02-index-failure-and-cost-model.md","title":"02 · 索引失效场景与代价模型","kind":"flow","secs":[{"h":"一、索引失效清单（逐条给改写）","s":"（因为 B+ 树里 NULL 被存在索引最左侧）。「IS NULL 一定失效」是常见误记。","c":null},{"h":"二、最左前缀的「断裂点」","s":"对联合索引 KEY idx(a, b, c)，WHERE 能用到几列，取决于从左起连续匹配：","c":null},{"h":"三、选择性（区分度）：为什么低选择性列不该单独建索引","s":"原因：走二级索引需要回表。若命中 30% 的行，回表 30 万次随机 I/O，","c":null},{"h":"四、回表 vs 覆盖索引：代价的定量对比","s":"设表 T 有 N 行，需要按 WHERE k = v 取 (k, payload) 两列：","c":null},{"h":"五、优化器为什么会选错","s":"三个常见原因：","c":null}]},{"id":"db-ch04/03-slow-query-and-sql-rewrite","file":"03-slow-query-and-sql-rewrite.md","title":"03 · 慢查询定位与 SQL 改写实战","kind":"flow","secs":[{"h":"一、先把慢 SQL 找出来","s":"日志是纯文本，用 mysqldumpslow -s t -t 10 slow.log 排序取 Top10，","c":{"lang":"sql","code":"SHOW VARIABLES LIKE 'slow_query_log';          -- 是否开启\nSHOW VARIABLES LIKE 'long_query_time';         -- 阈值（秒），默认 10\nSHOW VARIABLES LIKE 'log_queries_not_using_indexes';\n\nSET GLOBAL slow_query_log = ON;\nSET GLOBAL long_query_time = 1;                -- 生产建议 0.5~1s\nSET GLOBAL log_queries_not_using_indexes = ON; -- 记录未走索引的查询（日志量大，谨慎）"}},{"h":"二、深分页：LIMIT offset, n 的线性代价","s":"MySQL 必须先扫描并丢弃前 1000000 行才能返回 20 行——代价随 offset 线性增长。","c":{"lang":"sql","code":"SELECT * FROM orders ORDER BY id LIMIT 1000000, 20;"}},{"h":"三、JOIN 优化：小表驱动大表","s":"因此 驱动表（外层循环）行数越少越好，且被驱动表的关联列必须有索引","c":{"lang":"sql","code":"-- 假设 dept 只有 10 行，emp 有 100 万行\nSELECT * FROM dept d JOIN emp e ON e.dept_id = d.id;\n-- 优化器会选 dept 作驱动表：10 次外层 × 每次走 e.dept_id 索引\n-- 若反过来以 emp 驱动：100 万次外层 × 每次查 dept（无索引则全扫）→ 灾难"}},{"h":"四、子查询 vs JOIN","s":"MySQL 5.7+ 支持派生表合并（derived_merge），但含 GROUP BY/LIMIT/聚合时无法合并。","c":null},{"h":"五、排序与分组：消灭 filesort 与 temporary","s":"1. ORDER BY 的列顺序与索引顺序一致（或完全相反，可反向扫）；","c":{"lang":"sql","code":"-- 索引 KEY idx(a, b)\nSELECT * FROM t WHERE a = 1 ORDER BY b;        -- 可消除 filesort\nSELECT * FROM t WHERE b = 1 ORDER BY a;        -- 需要 filesort（缺左前缀 a）\nSELECT * FROM t ORDER BY a, b DESC;            -- 需要 filesort（方向不一致）"}},{"h":"六、其他高频改写","s":"","c":null}]},{"id":"db-ch04/04-statistics-index-governance","file":"04-statistics-index-governance.md","title":"04 · 执行计划之外：统计信息、索引治理与上线规范","kind":"flow","secs":[{"h":"一、连接池与预编译：计划缓存的双刃剑","s":"PreparedStatement 在 MySQL 侧有两条路：","c":null},{"h":"二、统计信息：优化器的眼睛","s":"对倾斜列的等值查询估算改善明显：","c":{"lang":"sql","code":"SHOW INDEX FROM orders;                 -- 看每列的 Cardinality\nANALYZE TABLE orders;                   -- 手动更新统计信息\nSHOW VARIABLES LIKE 'innodb_stats_persistent';      -- 是否持久化统计信息\nSHOW VARIABLES LIKE 'innodb_stats_auto_recalc';     -- 是否自动重算"}},{"h":"三、索引治理：少的、多的、没用的","s":"读多写少的表（配置、字典）可以多建。删除索引前必须确认：","c":null},{"h":"四、上线治理：把优化前置到开发阶段","s":"一套可落地的准入规则：","c":null},{"h":"五、三种连接算法：什么时候谁赢","s":"Hash Join 的引入让「等值连接 + 无索引」的代价从 O(|R|·|S|) 降到接近线性——","c":null}]}],"exams":[{"kind":"choice","q":"关于 EXPLAIN 的 rows 与 filtered 列，下列说法正确的是","stem":"执行计划里这两列各自表示什么？","opts":[{"k":"A","t":"rows 是实际返回的行数，filtered 是无用的装饰列"},{"k":"B","t":"rows 是优化器根据统计信息估算的扫描行数；filtered 是存储引擎返回后经条件过滤剩下的百分比"},{"k":"C","t":"rows 是磁盘 I/O 次数，filtered 是索引命中率"},{"k":"D","t":"rows 与 filtered 都只在 EXPLAIN ANALYZE 中才有意义"}],"ans":"B","why":"rows 是「估算」而非实测，统计信息过时就会偏差很大；filtered 表示该访问路径过滤后剩余行占比，两者相乘才是最终参与 join 的估算行数。要实测必须用 EXPLAIN ANALYZE（MySQL 8.0.18+）。"},{"kind":"choice","q":"下列 EXPLAIN type 取值中，性能最好的与最差的分别是","stem":"从 const / ref / range / index / ALL 中选出最好与最差。","opts":[{"k":"A","t":"最好 index，最差 ALL"},{"k":"B","t":"最好 const，最差 ALL"},{"k":"C","t":"最好 range，最差 index"},{"k":"D","t":"最好 ref，最差 range"}],"ans":"B","why":"阶梯为 system > const > eq_ref > ref > range > index > ALL。const 表示通过主键/唯一索引等值定位到最多一行；ALL 是全表扫描。特别注意 index 虽然带「index」字样，其实是扫整棵索引树，通常仍属需优化项。"},{"kind":"fix_error","q":"修复索引失效：在索引列上套函数","stem":"表 orders 上有普通索引 idx_created(created_at)。以下查询走不了索引，请改写它并说明原因： sql SELECT COUNT() FROM orders WHERE YEAR(created_at) = 2026;","opts":[],"ans":"SELECT COUNT() FROM orders WHERE created_at >= '2026-01-01' AND created_at < '2027-01-01';","why":"核心原则：索引列必须「裸奔」，任何函数、运算、隐式类型转换都会让它失去可定位性。改写后 type 由 ALL 变为 range。"},{"kind":"output","q":"读懂一份 EXPLAIN：哪张表是瓶颈","stem":"给定执行计划片段： id | table | type | key | rows | filtered | Extra 1 | o | ALL | NULL | 98000 | 10.00 | Using where 1 | u | eq_ref| PRIMARY | 1 | 100.00 | NULL 请指出瓶颈表、原因，以及可能的修复方向。","opts":[],"ans":"","why":"读 EXPLAIN 的顺序：先看 type（有无 ALL）、再看 key（是否 NULL）、然后看 rows（估算扫描量）与 filtered（过滤比）。ALL + key=NULL 是最典型的「缺索引」信号。"},{"kind":"coding","q":"为高频列表查询设计覆盖索引","stem":"订单表 orders(order_id PK, user_id BIGINT, status TINYINT, amount DECIMAL, created_at DATETIME)，业务上最频繁的查询是： sql SELECT order_id, amount FROM orders WHERE user_id = ? AND status = ? ORDER BY created_at DE…","opts":[],"ans":"ALTER TABLE orders ADD INDEX idx_user_status_time_amount (user_id, status, created_at, amount); -- 验证 EXPLAIN SELECT order_id, amount FROM orders WHERE user_id…","why":"判据：Extra 中同时出现 Using index（不回表）且没有 Using filesort（无额外排序），即为理想计划。"},{"kind":"coding","q":"优化深分页查询","stem":"以下查询在深页时极慢（OFFSET 很大），请给出至少两种优化方案并比较： sql SELECT id, title, created_at FROM articles ORDER BY id LIMIT 10 OFFSET 999990;","opts":[],"ans":"-- 方案一：延迟关联（先走覆盖索引取主键，再回表取列） SELECT a.id, a.title, a.created_at FROM articles a JOIN (SELECT id FROM articles ORDER BY id LIMIT 10 OFFSET 999990) t ON a.id = t.…","why":"结论：游标分页 > 延迟关联 > 朴素 LIMIT（在深页场景下）。差异随 OFFSET 增大而放大，见 examples/ex07 的代价模型。"},{"kind":"coding","q":"LeetCode 180 · 连续出现的数字（consecutive-numbers）","stem":"找出在 logs 表里至少连续出现三次的数字。可用窗口函数（ROW_NUMBER 分组差分）或自连接三份表实现。","opts":[],"ans":"SELECT DISTINCT l1.num AS ConsecutiveNums FROM logs l1 JOIN logs l2 ON l1.id = l2.id - 1 AND l1.num = l2.num JOIN logs l3 ON l2.id = l3.id - 2 AND l2.num = l3.n…","why":"自连接思路：三张表按 id 相邻且 num 相等。等价窗口函数写法：用 id - ROW_NUMBER() OVER (PARTITION BY num ORDER BY id) 得到分组键，同一组内 count>=3 的 num 即为答案。"},{"kind":"coding","q":"LeetCode 1321 · 餐馆营业额变化增长（restaurant-growth）","stem":"计算每天及之前 6 天的总营业额与「已营业至少 7 天的顾客」平均消费额。核心是滑动窗口 + 日期区间过滤，需要判断优化器能否用上 (visited_on) 上的索引。","opts":[],"ans":"SELECT visited_on, SUM(amount) AS amount, ROUND(SUM(amount) / 7, 2) AS average_amount FROM customer WHERE visited_on BETWEEN (SELECT MIN(visited_on) + INTERVAL…","why":"先用子查询定出有效日期区间（至少已营业 7 天），再按日期聚合。把区间条件下推到 WHERE 而非 HAVING，可以让 (visited_on) 索引做 range 扫描而不是全表扫后过滤。"}],"works":[{"h":"把 rows 当成实际扫描行数","d":"rows 是优化器基于统计信息的估算值，可能偏差一到两个数量级。要看真实值必须用 EXPLAIN ANALYZE（8.0.18+）。这条几乎每场面试都会问。"},{"h":"误以为 IS NULL 一定不走索引","d":"列允许 NULL 时，NULL 值存在 B+ 树最左侧，IS NULL 可以走索引。「IS NULL 必然失效」是错的；真正失效的是「列定义为 NOT NULL 还去查 IS NULL」（条件恒假）。"},{"h":"把 IN 当成范围条件","d":"在联合索引 (a,b,c) 上，a = 1 AND b IN (2,3) AND c = 4 三列都能用（IN 被展开为多个等值区间）。只有 >、<、BETWEEN 这类真范围才会让后续列断裂。"},{"h":"混淆 Using index 与 Using index condition","d":"前者是覆盖索引（不回表），后者是 ICP（索引下推，条件在引擎层过滤，仍可能回表）。二者含义完全不同，是最高频的概念混淆点。"},{"h":"把 index 当成好信号","d":"type = index 是全索引扫描（扫完整棵索引树），只是「扫的对象是索引而非表」，本质上仍是全扫。它优于 ALL，但绝不算好。"},{"h":"只看 key 有值就以为索引生效了","d":"必须同时看 type、key_len、rows、filtered。key_len 能反推实际用到了联合索引的前几列，这是验证最左前缀的唯一可靠手段。"},{"h":"对索引列使用函数或隐式类型转换","d":"WHERE DATE(created_at) = '2026-01-01'、WHERE varchar_col = 123 都会让索引失效。改写为范围条件、或把参数写成与列一致的类型。"},{"h":"深分页只会加 LIMIT","d":"LIMIT 1000000, 20 的代价随 offset 线性增长（要先扫描并丢弃）。优化要用延迟关联（子查询只取主键）或游标法（WHERE id > last_id），后者前提是分页键唯一且单调。"}],"asks":[{"q":"EXPLAIN 输出里你最关注哪几列？给出你的排查顺序。","a":"排查顺序（从信号最强到最弱）： 1. type：出现 ALL 就是全表扫描，第一优先级；index 是扫整棵索引树，也算需优化。理想是 const / eq_ref / ref / range。 2. key：为 NULL 说明该表压根没用上索引（可能没建，也可能被函数/隐式转换废掉了）。 3. possible_keys 有值但 key=NULL：典型「有索引却不用」，去查 WHERE、LIKE…","fu":["rows 估算和真实差距很大时怎么排查？","Using index condition 和 Using index 有什么区别？"],"tag":"通用/阿里"},{"q":"什么情况下明明建了索引，优化器却不用它？","a":"常见六类，本质都是「破坏了索引列的可定位性」： 1. 索引列被函数/运算包裹：WHERE YEAR(created_at)=2026、WHERE id+1=5。改成区间条件 created_at >= '2026-01-01' AND < '2027-01-01'。 2. 隐式类型转换：user_id 是 INT 却写 = '123'，MySQL 会对列做 CAST，等价于套了函数。传入正确类型即…","fu":["为什么选择性差的列做索引反而更慢？","函数索引（MySQL 8.0.13+）能解决第 1 类问题吗？"],"tag":"通用/字节"},{"q":"什么是回表？覆盖索引为什么能避免回表？","a":"回表：InnoDB 的二级索引叶子节点存的是「索引列 + 主键值」，不存整行。当查询需要的列不在二级索引里时，必须拿主键再去聚簇索引（主键索引）查一次拿完整行 —— 这就是回表。若命中 N 行，就是 N 次随机 I/O。 覆盖索引：把查询涉及的所有列都放进索引，使索引本身就能回答查询，无需回表。 sql -- 查询: SELECT order_id, amount FROM orders WHER…","fu":["为什么 order_id 是主键却也能算进覆盖列？","覆盖索引对写入性能有什么代价？"],"tag":"通用/阿里"},{"q":"联合索引的列序怎么定？为什么范围条件之后的列会失效？","a":"定序三原则： 1. 等值条件列放最左，选择性高的排前面（过滤性越强越先缩小范围）。 2. 范围条件列必须排在等值列之后。 3. ORDER BY 的列尽量紧随等值列，让索引天然有序，避免 Using filesort。 范围之后为何失效：B+树整体按「(a,b,c) 字典序」排序。当 a 是等值 a=1 时，子区间内 b 有序，b 上还能继续定位；但一旦 b > 2 是范围，落在该范围内的行「c…","fu":["如果查询是 WHERE a=1 ORDER BY b，索引 (a,b) 能否避免 filesort？","为什么 WHERE a>1 ORDER BY b 用 (a,b) 仍会 filesort？"],"tag":"通用/阿里"}]},{"id":"db-ch05","subj":"database","title":"存储过程 / 触发器 / 自定义函数","summary":"存储过程与函数定义、DELIMITER、参数模式；触发器 BEFORE/AFTER 与 NEW/OLD；游标；与应用程序端逻辑的职责边界。","concepts":[{"id":"db-ch05/01-stored-procedure-and-function","file":"01-stored-procedure-and-function.md","title":"01 · 存储过程与自定义函数：定义、DELIMITER 与参数模式","kind":"stack","secs":[{"h":"一、存储过程与自定义函数：定义、调用与差异","s":"MySQL 中两者的最小完整定义（注意 DELIMITER 的用法在第二节解释）：","c":{"lang":"sql","code":"DELIMITER $$\nCREATE PROCEDURE p_add_employee(\n    IN  p_name   VARCHAR(20),\n    IN  p_salary DECIMAL(10,2),\n    OUT p_new_id BIGINT\n)\nBEGIN\n    INSERT INTO employee(name, salary) VALUES (p_name, p_salary);\n    SET p_new_id = LAST_INSERT_ID();\n…"}},{"h":"二、参数模式 IN / OUT / INOUT 与 DELIMITER 的作用","s":"而客户端默认以 ; 作为「语句结束、可以发送了」的信号，","c":{"lang":"sql","code":"DELIMITER $$\nCREATE PROCEDURE p_discount(\n    IN    p_amount  DECIMAL(10,2),   -- 只读副本\n    IN    p_rate    DECIMAL(5,4),    -- 只读副本\n    OUT   p_final   DECIMAL(10,2),   -- 进入即 NULL, 由过程写回\n    INOUT p_counter INT              -- 保留初值, 可读可写\n)\nBEGIN\n    SET p_final = p_amount * (1 - p_rate);\n…"}}]},{"id":"db-ch05/02-triggers-new-old-and-audit","file":"02-triggers-new-old-and-audit.md","title":"02 · 触发器：ECA 模型、BEFORE/AFTER 时序与 NEW/OLD 行镜像","kind":"timeline","secs":[{"h":"一、触发器的 ECA 模型与 BEFORE / AFTER 时序","s":"触发器（trigger）是由数据修改事件自动激活的一段过程化代码，用户不能显式调用它。","c":{"lang":"text","code":"E (Event)     : INSERT / UPDATE / DELETE  (可加 OF col 限定列)\nC (Condition) : WHEN 子句 (可选)\nA (Action)    : BEGIN ... END 内的过程化语句"}},{"h":"二、NEW / OLD 行镜像的可用性矩阵与审计日志落地","s":"NEW 与 OLD 是触发器里两个行镜像（row image）伪记录，分别代表「修改后的行」和「修改前的行」。","c":{"lang":"sql","code":"CREATE TABLE salary_audit (\n    audit_id   BIGINT AUTO_INCREMENT PRIMARY KEY,\n    emp_id     BIGINT,\n    old_salary DECIMAL(10,2),\n    new_salary DECIMAL(10,2),\n    op         VARCHAR(8),\n    changed_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n…"}}]},{"id":"db-ch05/03-cursors-and-flow-control","file":"03-cursors-and-flow-control.md","title":"03 · 游标与流程控制：一次一记录的过程化补偿","kind":"timeline","secs":[{"h":"一、游标：DECLARE / OPEN / FETCH / CLOSE 与 CONTINUE…","s":"关系模型的原则是一次一集合（set-at-a-time）——你描述「要什么」，不描述「怎么一行行取」。","c":{"lang":"sql","code":"DELIMITER $$\nCREATE PROCEDURE p_raise_all(IN p_pct DECIMAL(5,2))\nBEGIN\n    -- ① 变量声明\n    DECLARE v_id   BIGINT;\n    DECLARE v_sal  DECIMAL(10,2);\n    DECLARE v_done INT DEFAULT 0;                       -- 结束标志\n    -- ② 游标声明（必须在变量与 handler 之前/之后的固定位置）\n    DECLARE cur_emp CURSOR FOR\n…"}},{"h":"二、流程控制：IF / CASE / WHILE / LOOP / REPEAT","s":"存储程序里的流程控制是 SQL/PSM 的过程化骨架，五件套如下：","c":{"lang":"sql","code":"-- ① IF / ELSEIF / ELSE\nIF v_score >= 90 THEN SET v_grade = 'A';\nELSEIF v_score >= 60 THEN SET v_grade = 'B';\nELSE SET v_grade = 'F'; END IF;\n\n-- ② CASE（两种形态）\nCASE v_code                                  -- 简单 CASE：与一个表达式比较\n    WHEN 1 THEN SET v_name = 'NEW';\n    WHEN 2 THEN SET v_name = 'PAID';\n…"}}]},{"id":"db-ch05/04-boundary-with-application","file":"04-boundary-with-application.md","title":"04 · 与应用程序端逻辑的职责边界","kind":"stack","secs":[{"h":"一、为什么互联网公司普遍不用存储过程","s":"这不是「存储过程不好」，而是架构形态变了。存储过程的前提是「一台强大的数据库 + 一群瘦客户端」；","c":null},{"h":"二、动态 SQL 拼接与注入；存储过程内的事务语义","s":"存储过程里有一项能力天然危险：动态 SQL。MySQL 用 PREPARE/EXECUTE 执行运行时拼接的字符串。","c":{"lang":"sql","code":"-- ✗ 危险：把用户输入直接拼进 SQL 文本\nDELIMITER $$\nCREATE PROCEDURE p_search_bad(IN p_kw VARCHAR(50))\nBEGIN\n    SET @sql = CONCAT('SELECT * FROM article WHERE title LIKE ''%', p_kw, '%''');\n    PREPARE stmt FROM @sql;\n    EXECUTE stmt;                 -- p_kw = 'x'' OR ''1''=''1' -> 全表泄露\n    DEALLOCATE PREPARE stmt;\nEND$$\n…"}}]}],"exams":[{"kind":"choice","q":"关于存储过程 OUT 参数模式，下列说法正确的是","stem":"存储过程 p(IN a INT, OUT b INT, INOUT c INT) 中，关于形参在过程体入口处的状态，正确的是：","opts":[{"k":"A","t":"b 保留调用者传入的值，过程内可读；c 被置为 NULL"},{"k":"B","t":"b 在入口被重置为 NULL，只能由过程写回；c 保留调用者传入的初值，可读可写并回传"},{"k":"C","t":"b 与 c 都必须由调用者传入非空值，否则报错"},{"k":"D","t":"b 与 c 等价，都是值传递，过程内的修改都不会回传"}],"ans":"B","why":"IN 是值传递的只读副本（默认模式，过程内改写不回传）；OUT 在进入过程时被重置为 NULL，只负责把结果带出；INOUT 兼具两者：保留初值、可读可写、最终回传。因此调用端 CALL p(1, @b, @c) 里的 @b、@c 必须是用户变量或局部变量，不能写字面量。"},{"kind":"choice","q":"关于 DELIMITER，下列说法正确的是","stem":"定义存储过程时为什么要先写 DELIMITER $$？","opts":[{"k":"A","t":"DELIMITER 是 MySQL 服务器语法，服务器靠它识别复合语句的边界"},{"k":"B","t":"DELIMITER 是客户端指令（如 mysql 命令行），用于临时改变语句结束符，使 BEGIN...END 内部分号…"},{"k":"C","t":"DELIMITER 用于设置字符集，与语句边界无关"},{"k":"D","t":"DELIMITER 只对存储函数无效，存储过程必须用分号收尾"}],"ans":"B","why":"客户端默认以 ; 判定「语句结束、可以发送」。BEGIN ... END 内部自带 ;，不加 DELIMITER 会在第一个内部分号处把半截语句发出去，服务器报 ERROR 1064。DELIMITER 是客户端解析约定、不发给服务器，所以「命令行报错、JDBC 可能通过」并不矛盾。定义完成后必须 DELIMITER ; 恢复。"},{"kind":"choice","q":"触发器里 NEW / OLD 的可用性","stem":"在行级触发器中，NEW 与 OLD 行镜像的可用性正确的是：","opts":[{"k":"A","t":"INSERT 两者都可用；DELETE 两者都可用"},{"k":"B","t":"INSERT 只有 NEW；UPDATE 两者都有；DELETE 只有 OLD"},{"k":"C","t":"INSERT 只有 OLD；DELETE 只有 NEW"},{"k":"D","t":"三种事件下 NEW 与 OLD 都始终可用"}],"ans":"B","why":"矩阵由「行版本数量」决定：INSERT 引入一个新版本（无旧版本）→ 只有 NEW；DELETE 移除一个旧版本（无新版本）→ 只有 OLD；UPDATE 是新旧替换 → 两者都有。在 DELETE 触发器里引用 NEW.col 会报无定义。另外只有 BEFORE 型触发器可以改写 NEW。"},{"kind":"fix_error","q":"修复游标过程：声明顺序错误 + 死循环","stem":"下面这段存储过程有两个缺陷：声明顺序不合法，且循环无法正常结束。请指出并给出修复后的完整定义。 sql DELIMITER $$ CREATE PROCEDURE p_raise(IN p_pct DECIMAL(5,2)) BEGIN DECLARE v_done INT DEFAULT 0; DECLARE cur_emp CURSOR FOR SELECT id, salary FROM e…","opts":[],"ans":"DELIMITER $$ CREATE PROCEDURE p_raise(IN p_pct DECIMAL(5,2)) BEGIN -- 强制顺序: 局部变量 -> 条件 -> 游标 -> 处理器 DECLARE v_id BIGINT; DECLARE v_sal DECIMAL(10,2); DECLARE v_…","why":"两个考点：DECLARE 的顺序是硬性规定；CONTINUE 型 handler 不会自动退出循环，必须显式 LEAVE。"},{"kind":"output","q":"估算触发器的执行次数与审计表写入行数","stem":"表 emp(id, salary) 有 10000 行。执行前建好一个 AFTER UPDATE ON emp FOR EACH ROW 的触发器，其内容为：当 NEW.salary <> OLD.salary 时向 salary_audit 插入一行。 现在执行： sql UPDATE emp SET salary = salary + 100 WHERE id <= 100; -- 100 行…","opts":[],"ans":"","why":"行级触发器的执行次数 = 语句影响的行数（不是语句条数）。这是「大表批量更新 + 触发器」性能事故的算术基础。"},{"kind":"coding","q":"为员工工资表设计审计触发器（含递归防御）","stem":"表结构： - employee(id BIGINT PK, name VARCHAR(20), salary DECIMAL(10,2), status TINYINT) - salary_audit(audit_id BIGINT AI PK, emp_id BIGINT, op VARCHAR(8), old_salary DECIMAL(10,2), new_salary DECIMAL(1…","opts":[],"ans":"DELIMITER $$ CREATE TRIGGER trg_emp_ai AFTER INSERT ON employee FOR EACH ROW BEGIN INSERT INTO salary_audit(emp_id, op, old_salary, new_salary) VALUES (NEW.id,…","why":"判据：三事件留痕 + <> 条件 + 不碰本表 + binlog_format=ROW + 审计表无外键，五条齐全才算合格答案。"},{"kind":"coding","q":"LeetCode 196 · 删除重复的电子邮箱（delete-duplicate-emails）","stem":"从 Person 表中删除所有重复邮箱的记录，只保留 id 最小的一条。请给出 DELETE 写法。","opts":[],"ans":"-- 自连接: 删除「存在更小 id 且 email 相同」的行 DELETE p1 FROM Person p1 JOIN Person p2 ON p1.email = p2.email WHERE p1.id > p2.id; -- 等价子查询写法 DELETE FROM Person WHERE id NOT…","why":"自连接写法把「保留 id 最小」表达为「删掉所有存在更小同 email 的行」，一次集合操作即可，避免应用层逐行删除（游标逐行的等价反例）。子查询写法必须先在外层再包一层派生表，否则 MySQL 不允许在 DELETE 的子查询中引用被删表。"},{"kind":"coding","q":"LeetCode 626 · 换座位（exchange-seats）","stem":"交换 Seat 表中相邻的座位 id（相邻两两互换，最大 id 为奇数时最后一个不动），按 id 升序返回。","opts":[],"ans":"SELECT CASE WHEN id % 2 = 1 AND id = (SELECT MAX(id) FROM Seat) THEN id WHEN id % 2 = 1 THEN id + 1 ELSE id - 1 END AS id, student FROM Seat ORDER BY id;","why":"用 CASE 表达式在集合层面完成「相邻配对交换」：奇数列向后挪一位、偶数列向前挪一位，末尾奇数保持不动。这类「按位置配对」的题若用游标逐行改 id，既慢又容易在交换过程中撞主键唯一约束，是「集合操作优于逐行处理」的典型例证。"}],"works":[{"h":"忘记 DELIMITER，过程体被分号切碎","d":"客户端默认以 ; 判定「语句结束、可以发送」，BEGIN ... END 内部的 ; 会让它提前发送半截语句，报 ERROR 1064 且错误位置指向 BEGIN 或内部分号。正确做法：DELIMITER $$ 定义、END$$ 收尾、最后 DELIMITER ; 恢复。"},{"h":"以为 DELIMITER 是服务器语法","d":"它是客户端指令（命令行/Navicat 的解析约定），不会发给服务器。因此「同一段 CREATE PROCEDURE 在命令行报错、在 JDBC 里却可能通过」并不矛盾。"},{"h":"以为 OUT 参数能读到调用者传入的值","d":"OUT 形参在过程入口被重置为 NULL，只负责「带出」结果，读取它拿不到任何输入。要「既读又写」必须用 INOUT。"},{"h":"把 OUT/INOUT 的实参写成常量","d":"CALL p(1, 2, 3) 中第 3 个若是 OUT 参数会直接报错：可写实参必须是用户变量（@v）或局部变量。正确写法：CALL p(1, 2, @out); SELECT @out;。"},{"h":"DECLARE 顺序写反","d":"存储程序内必须严格按「局部变量 → 条件 → 游标 → 处理器」的顺序声明，顺序错误直接语法报错。这条几乎没有例外。"},{"h":"游标循环没有 CONTINUE HANDLER FOR NOT FOUND","d":"没有终止信号，FETCH 取空后不会退出，LOOP 无限执行、反复 UPDATE 同一行，典型症状是「数据库 CPU 打满、SHOW PROCESSLIST 看到同一条 UPDATE」。"},{"h":"混淆 CONTINUE 与 EXIT 型 handler","d":"CONTINUE HANDLER 触发后继续执行（所以必须自己写 IF done = 1 THEN LEAVE ... 退出）；EXIT HANDLER 触发后退出当前 BEGIN...END 块（不需要 done 标志）。二者混用会造成「循环提前退出」或「死循环」两种相反的 bug。"},{"h":"用 INSERT/DELETE 触发器的 NEW/OLD 写错对象","d":"INSERT 只有 NEW、DELETE 只有 OLD、UPDATE 两者都有。DELETE 触发器里引用 NEW.col 会直接报无定义。"}],"asks":[{"q":"存储过程和自定义函数有什么区别？各适合什么场景？","a":"四条核心差异： 1. 调用方式：过程用 CALL p(...)，是独立语句；函数出现在表达式里，如 SELECT f(x)、WHERE f(col) > 1。 2. 返回值：过程可返回 0 个或多个（OUT/INOUT、或直接返回结果集）；函数必须 RETURNS 恰好一个标量值。 3. 事务控制：过程体内可以写 COMMIT/ROLLBACK；函数体内禁止事务控制语句。 4. 配套约束：函数必须…","fu":["函数里的 DETERMINISTIC 声明不实，会带来什么后果？","为什么函数不能包含 COMMIT？"],"tag":"通用/阿里"},{"q":"IN / OUT / INOUT 三种参数模式的语义差别是什么？调用时有什么限制？","a":"| 模式 | 入口初值 | 过程内修改是否回传 | 典型用途 | |---|---|---|---| | IN（默认） | 调用者传入的值 | 不回传 | 输入条件 | | OUT | 被重置为 NULL | 回传 | 带回计算结果 | | INOUT | 调用者传入的初值 | 回传 | 累加器、状态回传 | 最反直觉的一点：OUT 不是「不传值」，而是「进去以后被清空」。所以在过程开头读到 OU…","fu":["为什么 OUT 参数不能传字面量？","用户变量 @v 与过程内 DECLARE 的局部变量有什么区别？"],"tag":"通用/腾讯"},{"q":"定义存储过程为什么要写 DELIMITER？它到底是谁在处理？","a":"问题根源：客户端（mysql 命令行等）默认以 ; 判定「语句结束、可以发送」。而 BEGIN ... END 复合体内部自带 ;，于是客户端会在第一个内部分号处把半截语句发出去，服务器报 ERROR 1064 (42000)，错误位置指向 BEGIN 或内部分号附近。 解法：DELIMITER $$ 把结束符临时换成 $$，过程体内的分号就只是内部分号；END$$ 才被视为语句结束；定义完之后…","fu":["如果不恢复 DELIMITER ; 会怎样？","为什么 JDBC 里通常不需要写 DELIMITER？"],"tag":"通用/百度"},{"q":"触发器的 BEFORE 和 AFTER 分别在什么时候执行？NEW 和 OLD 在什么事件下可用？","a":"执行时序： DML 语句 → BEFORE 触发器 → 约束检查与实际写盘（含二级索引维护）→ AFTER 触发器。 因此：BEFORE 阶段数据页还是旧值，可以改写即将写入的行（SET NEW.col = ...）；AFTER 阶段数据页已是新值，只能读取 NEW/OLD 做记录与联动。 NEW/OLD 可用性矩阵（必背）： | 事件 | OLD | NEW | |---|---|---| |…","fu":["为什么 AFTER 触发器改写 NEW 无效？","触发器写入会被业务事务回滚一起撤销吗？"],"tag":"通用/阿里"}]},{"id":"db-ch06","subj":"database","title":"范式与数据库建模","summary":"第一/二/三范式与 BCNF；函数依赖与候选键；反范式与冗余权衡；ER 建模与表设计；实体/关系映射。","concepts":[{"id":"db-ch06/01-functional-dependency-and-closure","file":"01-functional-dependency-and-closure.md","title":"01 · 函数依赖、Armstrong 公理与候选键求解","kind":"flow","secs":[{"h":"一、函数依赖：完全依赖、部分依赖、传递依赖","s":"中的任意两个元组 t1、t2，只要 t1[X] = t2[X] 就必然 t1[Y] = t2[Y]，","c":{"lang":"text","code":"完全函数依赖  K ──决定──▶ A     且 K 的**任何真子集**都决定不了 A\n部分函数依赖  K ──决定──▶ A     但存在真子集 K' (K' ⊂ K) 也决定 A\n传递函数依赖  A ──▶ B ──▶ C     且 B ↛ A, C ⊄ B   ⇒  A → C 是传递依赖"}},{"h":"二、属性闭包 X+ 与候选键求解","s":"计算方法是不动点迭代：","c":{"lang":"text","code":"X+ := X\n重复:\n    对每个 FD (L → R) in F:\n        若 L ⊆ X+ 且 R ⊄ X+ :  X+ := X+ ∪ R\n直到 X+ 不再变化"}},{"h":"三、函数依赖集的最小覆盖（正则覆盖）","s":"1. Fc 与 F 等价（Fc+ = F+）；","c":{"lang":"text","code":"① 右部单一化: 把 X→YZ 拆成 X→Y 与 X→Z\n② 去除冗余 FD: 逐个尝试删掉 X→Y, 若删掉后 X 在剩余 F 下的闭包仍含 Y, 则它是冗余的\n③ 左部去冗余: 对 X→Y 与 X 中每个属性 a, 若 (X−{a})→Y 可由当前 F 推出, 则 a 冗余"}}]},{"id":"db-ch06/02-normal-forms-1nf-to-bcnf","file":"02-normal-forms-1nf-to-bcnf.md","title":"02 · 范式阶梯：从 1NF 到 BCNF","kind":"flow","secs":[{"h":"一、1NF 与 2NF：原子性与部分依赖","s":"违反示例（把多值属性塞进一列）：","c":{"lang":"text","code":"student(sno, name, phones)\nS1 | Zhang | '138..., 139...'     <- phones 是集合, 违反 1NF"}},{"h":"二、3NF：传递依赖与「主属性例外」","s":"等价的、更便于判定的形式化定义（强烈推荐用这个）：","c":{"lang":"text","code":"student(Sno, Sname, Dept, Dean)   候选键 = {Sno}\nF = { Sno -> Sname, Sno -> Dept, Dept -> Dean }\nSno -> Dept -> Dean, 且 Dept ↛ Sno, Dean 非主属性  =>  传递依赖, 违反 3NF\n分解: student(Sno, Sname, Dept)  +  dept(Dept, Dean)"}},{"h":"三、BCNF 与范式强度阶梯","s":"等价表述：每个决定因素都包含一个候选键（不允许非超键决定任何属性）。","c":{"lang":"text","code":"依赖 → 范式 的判据速查:\n  存在非原子属性                    => 违反 1NF\n  存在候选键真子集 -> 非主属性        => 违反 2NF\n  存在非超键 X -> 非主属性 (经中间属性) => 违反 3NF\n  存在非超键 X -> 任何属性            => 违反 BCNF"}}]},{"id":"db-ch06/03-decomposition-lossless-and-dependency-preserving","file":"03-decomposition-lossless-and-dependency-preserving.md","title":"03 · 模式分解：无损连接与保持依赖","kind":"flow","secs":[{"h":"一、两个正确性标准：无损连接与保持依赖","s":"把 R(U) 分解为 ρ = { R1(U1), R2(U2), ..., Rk(Uk) }（要求 U1 ∪ ... ∪ Uk = U），","c":{"lang":"text","code":"R(A,B,C)  F = { A->B, B->C }\n分解 ρ = { R1(A,C), R2(B,C) }\n  无 F 可作用 -> 无法把两行合并成同一行 -> 有损\n分解 ρ = { R1(A,B), R2(B,C) }        (交集 = B, B->C 成立)\n  -> 无损, 且 F 全部保持"}},{"h":"二、无损连接判定：表格法与二元分解快速判据","s":"(R1 ∪ ... ∪ R_{j-1} ∪ R_{j+1} ∪ ... ∪ Rk) ⊆ Rj+（或更常用的形式：某分片含原关系的候选键），","c":{"lang":"text","code":"① 造表: 行 = 分片 Ri, 列 = U 中属性\n   若 属性 A ∈ Ri, 填 ai (a 加列名); 否则填 bij (i 行号, j 列名)\n② 反复扫描每条 FD X->Y:\n   在 X 各列上取值相同的行, 把它们在 Y 各列的符号统一\n   规则: 若其中某格是 a?, 全部改为该 a?; 否则全部改为下标最小的 b??\n③ 停止条件: 表不再变化\n   判定: 若某一行全为 a?, 则无损; 否则有损"}},{"h":"三、保持依赖判定与 3NF 合成算法","s":"因此：既要无损又要保持依赖，就必须接受 3NF；要 BCNF 就要放弃依赖的局部可校验性。","c":{"lang":"text","code":"对 F 中每条 X -> Y:\n    计算 recovered = ∪_{Ri} ( closure( X ∩ Ri , F ) ∩ Ri )\n    若 Y ⊆ recovered 则该 FD 被保持\n若所有 FD 都被保持, 则分解 ρ 保持依赖 F"}}]},{"id":"db-ch06/04-er-modeling-keys-and-denormalization","file":"04-er-modeling-keys-and-denormalization.md","title":"04 · ER 建模、键的标准区分与反范式权衡","kind":"flow","secs":[{"h":"一、ER 建模：实体、属性与联系的落表方式","s":"ER（Entity-Relationship）模型由 Chen 于 1976 年提出，三要素：","c":{"lang":"text","code":"1:1  任选一端加外键 + UNIQUE 约束 (或让外键同时作主键)\n     user(uid PK)  profile(uid PK FK -> user.uid, bio)\n                ^ 外键同时是主键 -> 天然保证一对一\n\n1:N  在 **N 端** 加外键, 指向 1 端主键 (外键放 N 端!)\n     dept(did PK, dname)   emp(eid PK, ename, did FK -> dept.did)\n\nM:N  **必须**新建中间表, 主键 = 两端主键的组合\n     student(sid PK)  course(cid PK)  enrollment(sid, cid, grade, PK(sid,cid))\n…"}},{"h":"二、超键 / 候选键 / 主键 / 外键的标准区分","s":"集合关系：主键 ∈ 候选键 ⊆ 超键；且 候选键 ⊆ 超键 是真子集","c":{"lang":"text","code":"超键集合 (upward-closed)\n   {A,B}   {A,C}   {B,C}   {A,B,C} ...\n      \\      |      /\n       \\     |     /       候选键 = 极小元\n        {A,B}? /  ...       主键 = 选定其中 1 个\n外键: 本表某列 -> 被参照表的候选键, 语义是「引用」"}},{"h":"三、反范式：何时故意冗余","s":"所以：","c":{"lang":"text","code":"设 事实表 F 行数 n, 维度表 D 行数 m, 每个维度值对应 fanout = n/m 行事实\n\n范式化读:  n + m        (扫事实表 + 构建维度哈希表)\n反范式读:  n            (只扫事实表)          -> 每次读省 m\n范式化写(改维度值): 1\n反范式写(改维度值): fanout                    -> 每次写多 fanout-1\n\n盈亏平衡读写比  R/W 阈值 = (fanout - 1) / m\n当 R/W > 阈值 时, 反范式在操作计数上占优"}}]}],"exams":[{"kind":"choice","q":"关于「满足 3NF 但不满足 BCNF」，下列说法正确的是","stem":"已知关系模式 R(A,B,C)，函数依赖集 F = { AB→C, C→B }。 下面哪一项正确？","opts":[{"k":"A","t":"候选键只有 AB，且 R 满足 BCNF"},{"k":"B","t":"候选键为 AB 与 AC；C→B 的左部不是超键，故违反 BCNF；但 B 是主属性，故满足 3NF"},{"k":"C","t":"候选键为 AB 与 AC；因为 C→B 存在，所以连 2NF 都不满足"},{"k":"D","t":"R 不满足 3NF，因为存在非平凡函数依赖 C→B"}],"ans":"B","why":"先求候选键：AB+ = ABC、AC+ = ABC，故候选键为 AB 与 AC，主属性为 {A,B,C}（全部属性都是主属性）。BCNF 要求每个非平凡 FD 的左部都是超键：C→B 的左部 C 闭包为 {B,C} ≠ ABC，不是超键 ⇒ 违反 BCNF。3NF 的形式化定义允许「右边是主属性」的例外，B 是主属性 ⇒ 满足 3NF。2NF 只约束非主属性，本模式无（不存在的…"},{"kind":"choice","q":"下列哪个函数依赖属于「部分函数依赖」","stem":"关系模式 SC(Sno, Cno, Grade, Cname)，候选键为 (Sno, Cno)。 给定 F = { (Sno,Cno)→Grade, Cno→Cname }，哪一条是部分函数依赖？","opts":[{"k":"A","t":"(Sno,Cno) → Grade"},{"k":"B","t":"Cno → Cname"},{"k":"C","t":"两条都是部分依赖"},{"k":"D","t":"两条都不是部分依赖"}],"ans":"B","why":"部分依赖的定义是「存在候选键的真子集也能决定该属性」。Cno 是候选键 (Sno,Cno) 的真子集，且 Cno→Cname（Cname 是非主属性），故它是部分依赖，违反 2NF。(Sno,Cno)→Grade 中，Sno 与 Cno 单独都不能决定 Grade（同一学生不同课成绩不同、同一课程不同学生成绩不同），是完全函数依赖。注意判断依据是「候选键的真子集是否决定该属性」…"},{"kind":"output","q":"写出属性闭包 (CD)+ 与 (BD)+ 的结果","stem":"关系模式 R(A,B,C,D,E)，函数依赖集： F = { A→B, A→C, CD→E, B→D } 请分别写出 A+、BD+、CD+ 的结果（属性按字母序写出），并说明哪些是超键。","opts":[],"ans":"A+ = ABCDE (超键) BD+ = BD (非超键) CD+ = CDE (非超键)","why":"属性闭包的做法是不动点迭代：反复扫描所有 FD，只要左部已包含在结果集合里就把右部并进来，直到不再变化。判超键的唯一标准是 X+ = U。本题由 examples/ex01 真实跑出的结果一致（R=ABCDE，A+ 与 AE+ 为超键）。"},{"kind":"output","q":"判定分解 ρ 是否无损连接","stem":"关系模式 R(A,B,C)，F = { A→B, B→C }。 对下面两个分解分别判定无损连接性： ρ1 = { R1(A,B), R2(B,C) } ρ2 = { R1(A,C), R2(B,C) }","opts":[],"ans":"ρ1: 无损 (YES) ρ2: 有损 (NO)","why":"用二元分解快速判据：ρ 无损 ⟺ R1∩R2 → (R1−R2) 或 R1∩R2 → (R2−R1)。 ρ1：交集 {B}，B+ = {B,C}，覆盖了 R1−R2 = {A}？不；覆盖 R2−R1 = {C}？是。故无损。 ρ2：交集 {C}，C+ = {C}，既不覆盖 {A} 也不覆盖 {B}，故有损。 用表格法（例 ex05）也能得到同样结论：ρ1 的 R1 行会被统一成…"},{"kind":"coding","q":"编程求出一个关系模式的全部候选键","stem":"给定 R(A,B,C,D) 与 F = { AB→C, C→D, D→A }，完成两件事： 1. 写出全部候选键，并说明主属性集合； 2. 用 Python 实现「枚举子集 + 闭包验证 + 极小性过滤」的通用求解函数，打印候选键。","opts":[],"ans":"候选键 = ['AB', 'BC', 'BD'] 主属性 = ABCD","why":"B 不出现在任何 FD 的右部（属 L 类之外的情形：B 只出现在 AB→C 的左部），故 B 必属于每个候选键；从 {B} 出发闭包只有 B，必须逐步加属性。加上 A：AB+ = ABCD 成立 → AB 是候选键；加上 C：BC+ = BCDA 成立 → BC 是候选键（注意 C→D→A 的传递链）；加上 D：BD+ = BDA，再由 D→A 得 A，此时含 A 后 AB→…"},{"kind":"fix_error","q":"修复违反 2NF 与 3NF 的订单表","stem":"下面的宽表既存在部分依赖也存在传递依赖： sql CREATE TABLE order_flat ( order_id BIGINT, product_name VARCHAR(64), qty INT, user_id BIGINT, user_name VARCHAR(64), product_price DECIMAL(10,2), PRIMARY KEY (order_id, produc…","opts":[],"ans":"CREATE TABLE users ( user_id BIGINT PRIMARY KEY, user_name VARCHAR(64) NOT NULL ); CREATE TABLE products ( product_name VARCHAR(64) PRIMARY KEY, product_price D…","why":"修复的核心是把「不同粒度的实体」分开：用户、商品是独立实体（维度），订单是交易粒度，订单明细是「订单×商品」的 M:N 联系（联系自身属性 qty）。注意 order_item 的复合主键同时承担「不重复同一商品」的唯一约束与访问路径职能。可用 examples/ex12 的判定器实测：拆表前 2NF=NO、3NF=NO，拆表后四张表全部 BCNF。"},{"kind":"coding","q":"LeetCode 596 · 超过 5 名学生的课（M:N 中间表建模）","stem":"给定 courses(student, class) 形式的选课表，找出学生数不少于 5 人的课程。 本题是本章 M:N 联系的标准形态：学生与课程是多对多，选课关系本身就是中间表，(student, class) 就是它的复合主键。请用聚合 + HAVING 完成。","opts":[],"ans":"SELECT class FROM courses GROUP BY class HAVING COUNT(DISTINCT student) >= 5;","why":"建模视角：courses 就是 ER 图中「学生—选课—课程」这个 M:N 联系落成的中间表，字段为两端主键。若题目还要求给出成绩，成绩就属于联系自身的属性，应放在中间表里，而不是放到 student 或 class 表。"},{"kind":"coding","q":"LeetCode 184 · 部门工资最高的员工（1:N 连接的范式含义）","stem":"给定 Employee(id, name, salary, departmentId) 与 Department(id, name)，找出每个部门工资最高的员工。 请思考：为什么这里用两张表 + JOIN，而不是把部门名直接冗余在 Employee 里？","opts":[],"ans":"SELECT d.name AS Department, e.name AS Employee, e.salary AS Salary FROM Employee e JOIN Department d ON e.departmentId = d.id WHERE (e.departmentId, e.salary)…","why":"延伸考点：(departmentId, salary) IN (子查询) 是「行值构造器」比较，等价于按部门分组取最大工资再连接。若部门内最高工资并列，本写法会返回全部并列者 —— 这也是「用子查询而非窗口函数」时的经典陷阱（如需每组仅一行，应改用 ROW_NUMBER() OVER (PARTITION BY ...)）。"}],"works":[{"h":"把「主键」当成「候选键」","d":"主键是从候选键中人为选定 1 个；候选键可以有多个，未选中的候选键必须补 UNIQUE 约束，否则业务唯一性在库里没有约束力（并发下会插入重复行）。"},{"h":"认为「满足 3NF 就满足 BCNF」","d":"错的。标准反例：R(A,B,C)、F={AB→C, C→B}，候选键 AB、AC。C→B 的左部不是超键 ⇒ 违反 BCNF；但 B 是主属性 ⇒ 满足 3NF。原因是 3NF 有一条「主属性例外」：右边是主属性时允许左边非超键。"},{"h":"把「主属性」理解成「主键里的属性」","d":"主属性 = 出现在任一候选键中的属性。判定 3NF 时必须先把全部候选键求出来取并集，只看主键会判错（尤其在多候选键的模式上）。"},{"h":"检查 2NF 时只对主键做检查","d":"2NF 要求非主属性完全依赖每一个候选键。正确做法：求出全部候选键 → 定主属性集合 → 对每个候选键的真子集检查是否决定了非主属性。"},{"h":"认为 2NF 一定有意义","d":"若所有候选键都是单属性，则不存在真非空子集，2NF 自动满足。此时直接判 3NF 即可，别浪费时间找部分依赖。"},{"h":"把「部分依赖」理解成「左右两边都只有一个属性」","d":"部分依赖与属性个数无关，判断标准是「存在候选键的真子集能决定该非主属性」。(Sno,Cno)→Grade 是完全依赖（不能由 Sno 或 Cno 单独决定），而 Cno→Cname 才是部分依赖。"},{"h":"属性闭包只对单属性求","d":"闭包的输入是属性集。判定 AB→C 是否被 F 蕴含，必须算 (AB)+，而不是分别算 A+ 与 B+ 再取并集（那是错的，(AB)+ ⊋ A+ ∪ B+ 很常见）。"},{"h":"候选键判定漏掉「极小性」","d":"闭包等于 U 只能说明它是超键；还要验证去掉任一属性后闭包不再等于 U，才是候选键。少了这一步，{A,B} 与 {A} 会被同时误判为候选键。"}],"asks":[{"q":"什么是函数依赖？完全函数依赖、部分函数依赖、传递函数依赖之间是什么关系？","a":"函数依赖：设 R(U)，X,Y ⊆ U。若对 R 的任意合法实例中的任意两个元组 t1,t2，只要 t1[X]=t2[X] 就必有 t1[Y]=t2[Y]，则记 X→Y。它是对模式所有合法实例的约束（语义概念），不是从当前数据里统计出来的相关性。 三种依赖是层层递进地排除冗余： | 类型 | 定义 | 违反的范式 | |---|---|---| | 完全依赖 | X→Y，且 X 的任何真子集都不能…","fu":["为什么函数依赖的定义里强调「任意两个元组」而不是「存在两个元组」？","如果实际数据违反了某个 FD，说明设计有什么问题？"],"tag":"通用/美团"},{"q":"给你一个关系模式和函数依赖集，怎么求全部候选键？","a":"核心工具是属性闭包。X+ 是对 F 做不动点迭代：反复扫描每条 L→R，若 L ⊆ X+ 则把 R 并进来，直到不再变化。 判据：X 是超键 ⟺ X+ = U；X 是候选键 ⟺ X+ = U 且 X 的任意真子集都不是超键（极小性）。 实用步骤： 1. 属性分类剪枝（能省掉绝大部分枚举）： - L 类（只出现在 FD 左部）→ 必属于每个候选键； - R 类（只出现在右部）→ 必不属于任何候选键…","fu":["为什么「求全部候选键」在最坏情况下是 NP-hard 的？","候选键可以有多个，那主键是怎么定的？"],"tag":"通用/阿里"},{"q":"3NF 和 BCNF 的区别是什么？举一个满足 3NF 但不满足 BCNF 的例子。","a":"判定口径（背这两个就够）： - 3NF：对每个非平凡 X→A，下列至少一条成立 —— ① X 是超键；② A 是主属性。 - BCNF：对每个非平凡 X→A，X 必须是超键。 唯一的差别就是 3NF 的「主属性例外」：当右边是主属性时，左边可以不是超键。 标准反例：R(A,B,C)、F = { AB→C, C→B }。 1. 求候选键：AB+ = ABC、AC+ = ABC（因为 C→B），故候选…","fu":["BCNF 分解为什么不保证保持依赖？能举一个反例吗？","既然 3NF 够了，为什么还需要 BCNF？"],"tag":"通用/阿里"},{"q":"什么是无损连接分解？怎么判定一个分解是不是无损的？","a":"定义：把 R(U) 分解为 ρ = {R1,...,Rk}（∪Ui = U），若对 R 的所有合法实例 r 都有 r = π_R1(r) ⋈ ... ⋈ π_Rk(r)，则称 ρ 是无损连接分解。 注意「无损」的准确含义是连接后恰好还原原关系：既不能冒出伪元组，也不能丢失元组（不是「行数不变」这么模糊的说法）。 判定方法一：表格法（Chase） 1. 造表：行 = 分片 Ri，列 = 属性。属性属…","fu":["为什么表格法里统一符号是「有 a 取 a，无 a 取最小 b」，而不是随便取一个？","无损连接和保持依赖是一回事吗？"],"tag":"通用/字节"}]},{"id":"db-ch07","subj":"database","title":"备份恢复与权限安全","summary":"逻辑备份（mysqldump）与物理备份；binlog 与时间点恢复；用户与权限 GRANT/REVOKE；SQL 注入防范；敏感数据脱敏。","concepts":[{"id":"db-ch07/01-logical-vs-physical-backup-and-strategy","file":"01-logical-vs-physical-backup-and-strategy.md","title":"01 · 备份的两条路线：逻辑备份与物理备份","kind":"flow","secs":[{"h":"一、逻辑备份与物理备份：两种「备份」根本不是一回事","s":"按备份时数据库的可用状态再分一层：","c":{"lang":"text","code":"逻辑备份（sql 文本）                      物理备份（数据文件副本）\n+--------------------------+             +--------------------------+\n| CREATE TABLE `orders`... |             | ibdata1  orders.ibd      |\n| INSERT INTO `orders` ... |             | #ib_redo...  undo_001     |\n| INSERT INTO `orders` ... |             | (页 = 16KB 的二进制块)    |\n+--------------------------+             +--------------------------+\n        |  重放 SQL 重建                        |  直接挂载/拷贝回去\n        v \n…"}},{"h":"二、备份策略：全量 + 增量 + 校验的闭环","s":"一个可交付的备份策略由四个量共同确定：","c":{"lang":"text","code":"增量间隔 <= RPO                     （丢的数据不超过一个增量窗口）\n全量间隔 <= 最长可接受恢复链长度      （链越长，RTO 越大，出错概率越高）\n恢复耗时 ≈ 还原最近一份全量 + 重放链上所有增量\n存储需求 ≈ 保留期内全量份数 * 全量体积 + 增量份数 * 增量体积"}},{"h":"三、备份要「可信」：三条判据与恢复演练","s":"把「备份可信」拆成可验证的三条判据（本章示例的判据都落在这里）：","c":{"lang":"text","code":"备份 -> [判据1/2/3] -> 通过? --否--> 告警 + 重跑\n                          |\n                          是\n                          v\n                   定期在隔离库真实还原 -> 记录实际 RTO"}}]},{"id":"db-ch07/02-binlog-formats-and-pitr","file":"02-binlog-formats-and-pitr.md","title":"02 · binlog 与时间点恢复（PITR）","kind":"timeline","secs":[{"h":"一、binlog 到底记了什么：三种格式（STATEMENT / ROW / MIXED）","s":"MySQL 的二进制日志（binary log）是服务层的变更日志，与存储引擎层的","c":{"lang":"text","code":"  客户端 SQL\n      |\n      v\n  [ 服务层 ]  --写-->  binlog（逻辑事件，用于复制 / PITR）  --两阶段提交--> 存储引擎\n      |\n      v\n  [ InnoDB ]  --写-->  redo log（物理页变更，用于崩溃恢复）\n                --写-->  undo log（版本链，用于回滚与 MVCC）"}},{"h":"二、时间点恢复（PITR）的完整流程","s":"PITR 解决的问题是：误操作已经提交，但事务本身没问题，我要的是「回退时间」而不是「回滚事务」。","c":{"lang":"text","code":"t0 ---------- t1 ---------------- T_target ----- t2 -----------> 时间\n|             |                     |             |\n全量备份    备份点(位点/GTID)     目标恢复点     误删在 t2 执行\n（物理/逻辑）                                        |\n                                              这一段必须丢弃\n恢复步骤：restore(t0 全量) -> 重放 [t1, T_target] 的 binlog -> 核对 -> 放流量"}},{"h":"三、增量备份：数据增量与「日志增量」两条路线","s":"日常几乎不增加备份负担，而 PITR 能力随 binlog 保留期自然获得。","c":{"lang":"text","code":"数据增量路线：  全量(第 1 天) -> 增量(第 2 天) -> 增量(第 3 天)     恢复 = 全量 + 按序应用增量\n日志增量路线：  全量(第 1 天) + 常驻的 binlog                       恢复 = 全量 + 重放区间 binlog"}}]},{"id":"db-ch07/03-users-and-privileges-least-privilege","file":"03-users-and-privileges-least-privilege.md","title":"03 · 用户与权限模型：用户@主机、GRANT/REVOKE、最小权限","kind":"flow","secs":[{"h":"一、MySQL 的账号不是「用户」，而是「用户@主机」","s":"MySQL 里一个账号的身份是二元组 'user'@'host'：","c":{"lang":"text","code":"'app'@'10.0.0.5'     只允许从 10.0.0.5 连接\n'app'@'10.0.0.%'     允许 10.0.0.0/24 网段（% 是任意长度通配）\n'app'@'%'            允许任意主机（等价于一个可被任意来源尝试的账号）\n'app'@'localhost'    只允许本机 socket / 本地回环（注意与 '127.0.0.1' 是不同账号）"}},{"h":"二、GRANT / REVOKE 与角色","s":"角色的价值不在语法糖，而在权限治理：授权对象从「人」变成「岗位」，","c":{"lang":"sql","code":"-- 建账号（限制来源主机，不用 '%'）\nCREATE USER 'app'@'10.0.0.%' IDENTIFIED BY '<strong-password>';\n\n-- 只授业务库的必要动作\nGRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'app'@'10.0.0.%';\n\n-- 只读报表账号：库级 SELECT + 显式禁止写\nGRANT SELECT ON shop.* TO 'report'@'10.0.0.%';\n\n…"}},{"h":"三、最小权限：从原则到可执行的审计","s":"最小权限（least privilege）不是一句口号，而是三条可检查的动作：","c":{"lang":"text","code":"① 收窄来源：'app'@'%'  ->  'app'@'10.0.0.%'（按需再收窄到具体网段/主机）\n② 收窄对象：*. *  ->  shop.*  ->  shop.orders [可选: 列级]\n③ 收窄动作：ALL  ->  实际用到的 SELECT/INSERT/UPDATE/DELETE 子集"}}]},{"id":"db-ch07/04-sql-injection-masking-and-audit","file":"04-sql-injection-masking-and-audit.md","title":"04 · SQL 注入防范、脱敏加密与审计","kind":"flow","secs":[{"h":"一、SQL 注入：为什么它至今仍是头号 Web 漏洞","s":"注入的本质是代码与数据在同一通道里被拼接：","c":{"lang":"text","code":"正常：  语句结构固定，用户输入只落在「值」的位置\n        SELECT ... WHERE uname = ? AND pwd = ?        <- 结构由开发者写死\n注入：  用户输入改变的是「结构」\n        SELECT ... WHERE uname = 'x' AND pwd = '' OR '1'='1' --'\n                                                     ^^^^^^^^^^^^^^^ 结构被改写"}},{"h":"二、敏感数据的保护手段：脱敏、加密与视图","s":"同一条敏感数据（手机号、身份证、银行卡、地址）在不同场景下的保护目标不同：","c":{"lang":"text","code":"原值            掩码脱敏            假名化（加盐哈希）\n13812345678  -> 138****5678   ->  3bab6ed461b22bf8      (可关联, 不可还原)\nzhang@a.com  -> z***@a.com    ->  39ad582f3e2347f7"}},{"h":"三、审计日志与安全清单","s":"审计回答一个具体问题：「这条数据是谁在什么时候改的？」","c":{"lang":"text","code":"业务表 account                 审计表 audit_log（独立表/独立库，业务账号只被授予 INSERT）\n+----+--------+---------+      +-----+---------------------+-------+---------+-----+--------+--------------+\n| id | owner  | balance |      | seq | ts                  | actor | op      | id  | old    | new          |\n+----+--------+---------+      +-----+---------------------+-------+---------+-----+--------+--------------+\n|  1 | alice  |     800 | <---- |   3 | 2026-10-09T09:31:00 | dba \n…"}}]}],"exams":[{"kind":"choice","q":"关于逻辑备份与物理备份的取舍，下列说法正确的是","stem":"某业务库 800 GB，全部使用 InnoDB；业务要求 RTO 不超过 2 小时，并且偶发需要「只恢复其中一张表」。 下面哪一项描述最准确？","opts":[{"k":"A","t":"物理备份体积小、可跨版本恢复，因此应当只做物理备份"},{"k":"B","t":"逻辑备份便于单表恢复与跨版本迁移，但大库恢复慢；RTO 紧张时应以物理备份为主，同时保留逻辑备份或 binlog 承担单…"},{"k":"C","t":"只要备份命令退出码为 0，就说明备份可用于恢复，无需还原演练"},{"k":"D","t":"物理备份必须停库（冷备），无法在线执行"}],"ans":"B","why":"A 错：物理备份是页/文件级二进制副本，体积大、与版本强相关，跨版本恢复能力差。C 错：退出码 0 只说明命令跑完，是否可恢复必须靠校验（表名集合/行数/校验和）与真实还原演练来证明。D 错：XtraBackup 属于热备路线，通过拷贝期间记录 LSN、拷完用 redo 前滚收敛到一致状态，不需要停库。B 描述了正确的工程取舍：大库 + 紧 RTO 以物理备份为主，逻辑备份/b…"},{"kind":"choice","q":"用于时间点恢复（PITR）的 binlog，格式与配置应如何选择","stem":"团队需要把 binlog 用于两件事：① 从库复制；② 误删之后把主库恢复到误操作前一秒。 关于 binlog_format 与相关配置，下列说法正确的是","opts":[{"k":"A","t":"用 STATEMENT 最省空间，且重放结果与原始执行结果一定相同，适合 PITR"},{"k":"B","t":"用 ROW，重放结果确定、可精确到行；同时应显式配置 binlog_expire_logs_seconds（决定能回退多…"},{"k":"C","t":"用 MIXED 可以在 STATEMENT 与 ROW 之间按表切换，从而同时获得两者的优点"},{"k":"D","t":"格式无所谓，只要定期做全量备份就能恢复到任意时间点"}],"ans":"B","why":"A 错：STATEMENT 记录语句原文，遇到 NOW()、UUID()、RAND()、无 ORDER BY 的 LIMIT 等非确定性语句时，重放结果可能不同，会造成静默不一致。B 正确：ROW 记录行镜像，重放确定；同时日志保留期决定 PITR 的可回退范围，sync_binlog=1 才能在故障时不丢事件（对应 RPO=0 的诉求）。C 错：MIXED 是「按语句」而非按…"},{"kind":"output","q":"写出备份链复原后的表状态与一致性判据","stem":"某库做「全量 + 增量」备份链： 全量备份(T0) : accounts = [(1,alice,1000), (2,bob,500)] 增量1(2 条操作): INSERT (3,carol,200) ; UPDATE id=1 balance=800 增量2(2 条操作): INSERT (4,dave,300) ; DELETE id=2 线上库当前（已应用全链）状态为 [(1,alice,…","opts":[],"ans":"① 全链复原 = [(1,'alice',800), (3,'carol',200), (4,'dave',300)]，与线上库一致 = True ② 只到增量1 = [(1,'alice',800), (2,'bob',500), (3,'carol',200)]，与线上库一致 = False ③ 缺失行 id =…","why":"增量链是有方向的折叠：漏掉任意一环，恢复出来的就是「另一个时间点」的库，而不是「大致正确的库」。因此备份链的每一环都必须可校验（校验和 + 行数），并且定期做完整链的还原演练；链上任意一环损坏，其后所有状态都不可达。"},{"kind":"fix_error","q":"修复存在 SQL 注入的登录查询","stem":"下面的登录查询把外部输入直接拼进 SQL： python def login(con, uname, pwd): sql = \"SELECT id, role FROM users WHERE uname = '%s' AND pwd = '%s'\" % (uname, pwd) return con.execute(sql).fetchall() 攻击者传入 uname='x'、pwd=\"' O…","opts":[],"ans":"修复后传入同样的载荷：返回行数 = 0，越权读到全部用户 = False；users 表仍完好（行数 = 3）。","why":"参数化绑定把「SQL 结构」与「数据值」在协议层面分离：语句模板先被解析定型，参数在绑定阶段只作为值传入，因此引号与注释符不再具备语法意义，载荷只能被当成一个普通字符串去比较（返回 0 行）。但要注意参数化只覆盖「值」的位置：ORDER BY ?、表名、列名等标识符位置必须用白名单映射，否则要么报错，要么被逼回拼接从而重新引入注入。此外应配合最小权限（该账号不应有 DDL 权限…"},{"kind":"coding","q":"为核心表实现触发器审计日志","stem":"为 account(id, owner, balance) 建立审计：任何 INSERT/UPDATE/DELETE 都要写入audit_log(ts, actor, tbl, row_id, op, old_value, new_value)。 要求： 1. 用 AFTER INSERT/UPDATE/DELETE 三个触发器实现，记录前后值； 2. 触发器需要拿到「操作人」，而数据库触发器无法…","opts":[],"ans":"audit_log 记录数 = 4（= 业务写操作次数），可追溯到 21:42 由 ops 执行的删除","why":"触发器运行在数据库内部，看不到应用层的登录身份，因此需要一个「会话上下文」把操作人带进来：可以用一张单行 session 表（应用每次写前更新），也可以用用户变量 SET @actor = ... 再在触发器里读 @actor。审计表不可篡改靠权限隔离：业务账号只被授予审计表的 INSERT，不给 UPDATE/DELETE；更严格的做法是把审计表放到独立库或独立实例，并对审计…"},{"kind":"output","q":"由 RPO/RTO 反推备份频率与存储需求","stem":"给定： RPO = 15 分钟 RTO = 120 分钟 保留期 = 14 天 最长增量链 = 8 份 单份全量 = 200 GB 单份增量 = 5 GB 还原一份全量 = 60 分钟 重放一份增量 = 4 分钟 请算出：① 每天增量备份次数；② 每天全量备份次数；③ 保留期内全量与增量的份数；④ 保留期存储需求；⑤ 最坏恢复耗时，并判断 RPO 与 RTO 是否满足。","opts":[],"ans":"① 每天增量次数 = 1440 // 15 = 96 ② 每天全量次数 = 96 // 8 = 12 ③ 保留期内: 全量 = 12 14 = 168 份, 增量 = 96 14 = 1344 份 ④ 存储需求 = 168200 + 13445 = 33600 + 6720 = 40320 GB ⑤ 最坏恢复耗时 =…","why":"推导链是固定的：增量间隔 ≤ RPO（保证最多丢一个增量窗口的数据），全量间隔 = 最长可接受恢复链长度（链越长 RTO 越大、坏了就越难复原，所以要周期性重置基线）。存储需求 = 保留期内的全量份数 × 全量体积 + 增量份数 × 增量体积。最坏恢复耗时 = 还原最近一份全量 + 重放整条链上的全部增量。注意 RPO 与 RTO 是两个不同维度的约束：RPO 约束数据丢失量…"},{"kind":"coding","q":"实现最小权限判定器（主机通配 + 表级通配 + 默认拒绝）","stem":"给定授权表，每条为 (用户, 主机, 动作, 库, 表, grant_option)；其中主机与表字段支持 % 通配符（% 匹配任意长度字符），表字段取值 表示该库的全部表；动作字段取值 ALL 表示覆盖任意动作。 授权表内容： ('app', '10.0.0.5', 'SELECT', 'shop', 'orders', 0) ('app', '10.0.0.5', 'SELECT', 'sho…","opts":[],"ans":"ALLOW, DENY, DENY, DENY, ALLOW, DENY, ALLOW, DENY, DENY 统计: 允许 3 条 / 拒绝 6 条","why":"判定器是「五元组逐字段匹配 + 默认拒绝」的算法：用户与库要求精确相等；主机与表做 % 通配匹配（ 等价于该库的全部表）；动作要求精确相等或授权为 ALL。逐条推导：app@10.0.0.5 SELECT shop.orders 命中表级授权 → ALLOW；app DELETE shop.orders 无 DELETE 授权 → DENY；app SELECT shop.cu…"},{"kind":"coding","q":"LeetCode 1741 · 每名员工花费的总时间（事件日志聚合）","stem":"给定一张记录员工「进入/离开」事件的事件表，请按「员工 × 日期」聚合出每人每天停留的总时长。 本题与本章的审计日志主题同构：审计表记录的是「谁在什么时刻做了什么」，而把事件流按主体与时间窗聚合，是审计分析（如在岗时长、操作频次异常检测）最常见的下游查询。请用聚合 + 分组完成。","opts":[],"ans":"SELECT event_day AS day, emp_id, SUM(out_time - in_time) AS total_time FROM Employees GROUP BY event_day, emp_id;","why":"与本章的呼应有两层：① 审计日志本质上就是一张事件表，「按主体 + 时间窗聚合」是它最典型的分析查询；② 审计表设计时若把操作人与时间做成独立列（而不是塞进一个字符串字段），下游聚合才不需要解析文本 —— 这是「审计表字段设计要为查询服务」的直接体现。"}],"works":[{"h":"把「备份成功」当成「能恢复」","d":"退出码 0 只说明命令跑完了。备份闭环必须是「备份 + 校验 + 真实还原演练 + 记录实际 RTO」，缺任一环都等于没有可交付的备份能力。"},{"h":"用文件大小或耗时当备份正确的判据","d":"文件大小与用时跟引擎实现、压缩算法、页填充率相关，不可复现。正确判据是表名集合、每表行数、内容校验和（如主键有序拼接后的 sha256）。"},{"h":"只用校验和，不做语义比对","d":"校验和只能证明「备份与备份源一致」，证明不了「备份源本身正确」，也发现不了备份期间的部分提交。必须补上表名集合与行数、必要时再加外键完整性检查。"},{"h":"认为 --single-transaction 万能","d":"它只对 InnoDB 生效；库里有 MyISAM 表时会被加锁，且备份期间执行的 DDL 会让快照失效。混用引擎的库要么全量锁，要么先迁表。"},{"h":"不记录备份位点","d":"没有 --source-data=2 / gtid_mode 或 xtrabackup_binlog_info 记录的位点，PITR 就没有起点，只能全库重放。备份脚本必须把位点与备份文件一起存档。"},{"h":"误删后先重启或继续放流量","d":"重启会丢内存里尚未落盘的信息并可能触发自动恢复，继续写会让「需要丢弃的数据」变多。第一动作是降级为只读、保留现场、定位误操作时间与位点。"},{"h":"把 binlog 的 STATEMENT 当默认安全选项","d":"STATEMENT 记录 SQL 原文，NOW()、UUID()、RAND()、无 ORDER BY 的 LIMIT 等非确定性语句重放结果可能不同，会造成主从静默不一致。要用于复制或 PITR 就应使用 ROW。"},{"h":"在 ROW 格式的 binlog 里 grep 语句原文","d":"ROW 记录的是行镜像（base64 编码），看不到 SQL 文本。读日志要先用 mysqlbinlog --base64-output=DECODE-ROWS -vv 解码。"}],"asks":[{"q":"逻辑备份与物理备份怎么选？说说各自的原理与适用场景。","a":"原理差异：逻辑备份导出的是可重放的 SQL 文本（CREATE TABLE + INSERT），物理备份拷贝的是数据文件/页的二进制副本（ibd、redo、undo）。 | 维度 | 逻辑备份（mysqldump/mydumper） | 物理备份（冷拷/XtraBackup） | |---|---|---| | 产物 | SQL 文本，可读可裁剪 | 页副本，黑盒 | | 跨版本 | 好 | 差（…","fu":["--single-transaction 在什么情况下会失效？MyISAM 表怎么办？","XtraBackup 为什么不需要长时间持锁？它靠什么保证一致？"],"tag":"通用/阿里"},{"q":"线上被人误删了一张表，你怎么把它恢复出来？","a":"先分清两个目标：只救一张表，还是把整库回退到误操作之前。 第一步（最重要的 30 秒）：止血并保留现场 —— 立刻把库置为只读（FLUSH TABLES WITH READ LOCK 或应用侧降级），不要重启，不要让业务继续写。每多写一分钟，后续要丢弃的数据就多一分钟。 第二步：定位误操作。SHOW BINLOG EVENTS 或用 mysqlbinlog --base64-output=DECO…","fu":["为什么不能直接用从库顶上？延迟复制能帮上什么忙？","如果 binlog 只保留了 1 天，而误删发生在 3 天前，还有救吗？"],"tag":"通用/字节"},{"q":"binlog 的 STATEMENT、ROW、MIXED 有什么区别？为什么生产上一般用 ROW？","a":"| 格式 | 记录内容 | 优点 | 风险 | |---|---|---|---| | STATEMENT | SQL 语句原文 | 日志最小、可读 | 非确定性语句（NOW()、UUID()、RAND()、无 ORDER BY 的 LIMIT、用户变量）重放结果可能不同 → 主从静默不一致 | | ROW | 每行的前后镜像 | 重放确定、可精确恢复单行、下游订阅友好 | 日志体积最大 | |…","fu":["ROW 格式下为什么 grep 不到 SQL 语句？怎么读？","binlog_row_image=MINIMAL 有什么副作用？"],"tag":"通用/阿里"},{"q":"MySQL 的权限模型是怎样的？说说「用户@主机」和 GRANT/REVOKE 的粒度。","a":"主体是二元组 'user'@'host'：认证发生在连接阶段，服务器按「用户名 + 来源主机」在 mysql.user 里挑记录并校验凭据。因此同名不同主的账号是两套权限，'root'@'localhost' 与 'root'@'127.0.0.1' 是两个账号，'app'@'%' 等于允许任意来源尝试 —— 生产上要收窄成 'app'@'10.0.0.%'。 授权粒度：ON .（全局）→ ON…","fu":["为什么应用账号绝不能用 root，也不能给 ALL？","列级授权为什么通常不推荐，替代方案是什么？"],"tag":"通用/腾讯"}]},{"id":"db-ch08","subj":"database","title":"高可用 / 主从复制 / 分库分表","summary":"主从复制原理与延迟；读写分离；基于 Vitess 的分片（分库分表）；高可用架构与故障切换；数据一致性保障。","concepts":[{"id":"db-ch08/01-mysql-replication-and-read-write-split","file":"01-mysql-replication-and-read-write-split.md","title":"01 · 主从复制：binlog、relay log 与复制模式","kind":"timeline","secs":[{"h":"一、复制链路：binlog dump → relay log → 重放","s":"主库把每个已提交事务按 binlog_format 序列化写入本地 binlog（仅追加）。","c":{"lang":"text","code":"主库                                          从库\n┌────────────┐      COM_BINLOG_DUMP      ┌──────────────────────┐\n│ 事务提交     │  ◀────────────────────    │ IO_THREAD            │\n│    ↓        │      binlog events        │    ↓ 落盘（顺序追加）  │\n│ binlog      │  ─────────────────────▶   │ relay log            │\n└────────────┘                           │    ↓                 │\n   dump 线程                              │ SQL_THREAD 重放       │\n   （持有快照读 binlog）        \n…"}},{"h":"二、复制模式：异步 / 半同步 / 组复制","s":"三种模式的差别只在主库何时向客户端返回提交成功：","c":{"lang":"text","code":"异步       主库: 写 binlog → 引擎提交 → 返回客户端 ─────▶ 后台推给从库\n半同步     主库: 写 binlog → 等 ≥1 个从库 ACK → 引擎提交 → 返回客户端\n组复制     主库: 写 binlog → 广播给组 → 多数派达成一致 → 提交 → 返回客户端"}},{"h":"三、主从延迟的成因与「读己之写」","s":"延迟 = 「主库已提交」与「从库已可见」之间的时间差。它不是故障，而是异步复制的","c":{"lang":"text","code":"① 写后读主（pin to master）：会话在写操作后的一段时间窗内所有读都走主库；\n② 版本号等待：客户端带上「至少需要看到哪个版本」的位点，从库未追平则等待或改路由；\n③ 单调读：为会话记住「已读到的最大版本」，任何读都不允许返回比它更旧的版本。"}}]},{"id":"db-ch08/02-sharding-strategies-and-ids","file":"02-sharding-strategies-and-ids.md","title":"02 · 分库分表：切分维度、分片键与扩容","kind":"flow","secs":[{"h":"一、切分维度：范围 / 哈希 / 一致性哈希 / 基因法","s":"分片的本质是构造一个从「查找键」到「存储单元」的满射，并同时优化三个目标：","c":{"lang":"text","code":"分片      范围分片 key 数     哈希分片 key 数\nshard0    8000                2462\nshard1    667                 2499\nshard2    667                 2459\nshard3    666                 2580\n极差      7334                121\n标准差    3175.4              48.8\n最大占比  80.0%               25.8%"}},{"h":"二、分片键选择、跨分片 JOIN 与聚合","s":"examples/ex05 实测归并的正确性条件（1000 条记录、4 分片、k=10，","c":{"lang":"text","code":"① 高基数：取值足够多，避免大量数据落同一分片（性别/状态这类列不能做分片键）；\n② 业务强绑定：它是最高频查询的等值条件，否则每次查询都要广播全部分片；\n③ 不可变：一旦修改分片键，就要跨分片搬整行数据（几乎不可能安全完成）。"}},{"h":"三、分布式 ID 与二次分片（扩容）","s":"雪花位分配（examples/ex03 实测）：","c":{"lang":"text","code":"1 符号位 + 41 时间戳位 + 10 机器位 + 12 序列位 = 64 位\n单机每毫秒上限 = 2^12 = 4096  → 单机 409.6 万/秒\n单集群机器数上限 = 2^10 = 1024\n41 位毫秒可支撑 69 年"}}]},{"id":"db-ch08/03-high-availability-and-failover","file":"03-high-availability-and-failover.md","title":"03 · 高可用架构与故障切换","kind":"flow","secs":[{"h":"一、高可用架构：MHA / MGR / Orchestrator","s":"高可用（HA）的目标用两个指标刻画：RTO（恢复时间目标 = 可接受的最长不可用时长）","c":{"lang":"text","code":"        RPO 小（不丢数据）\n              ▲\n              │  MGR（多数派提交，自动选主）\n              │      · 3/5 节点，RPO=0，RTO 秒级\n              │\n   半同步 ────┤  半同步 + Orchestrator\n   （≥1 ACK） │      · RPO≈0，RTO 十秒级，需外部仲裁\n              │\n   异步复制 ──┤  主从 + MHA\n…"}},{"h":"二、故障切换：多数派投票、脑裂与 fencing","s":"一次正确的切换是有严格顺序的状态机：","c":{"lang":"text","code":"① 检测      心跳超时 >= 3 个周期（避免抖动误判）\n② 仲裁      仅多数派一侧可发起切换（q = N//2 + 1）\n③ Fencing   隔离/关停旧主，确认其不能再写（先做这一步！）\n④ 选新主    选 relay log 最完整 / GTID 最大的从库（减少数据丢失）\n⑤ 提升      STOP SLAVE -> RESET SLAVE ALL -> read_only=0\n⑥ 重定向    VIP / Proxy / 客户端 SDK 切换入口\n⑦ 收敛      其余从库 CHANGE MASTER TO 指向新主，校验 GTID 与行数"}}]},{"id":"db-ch08/04-cap-base-and-consistency","file":"04-cap-base-and-consistency.md","title":"04 · CAP / BASE 与一致性保障","kind":"flow","secs":[{"h":"一、CAP 与 BASE 的形式化理解","s":"CAP 的严格表述（Gilbert & Lynch, 2002）：在异步网络模型下，","c":{"lang":"text","code":"C（一致性）  = 线性一致（linearizability）：每个操作看似在其调用与返回之间的\n               某一瞬间原子生效，且所有操作的全序与真实时间一致；\nA（可用性）  = 每个**未发生故障**的节点都能在**有限时间**内返回响应（不是「大部分可用」）；\nP（分区容错）= 网络可能丢弃/延迟任意多消息，系统仍能继续运行。"}},{"h":"二、一致性保障手段：半同步、Quorum 与补偿","s":"一致性保障分三个层次，任何真实系统都需要后两层：","c":{"lang":"text","code":"① 预防（让不一致不发生）：单库事务 / 半同步复制 / Quorum 多副本写 / 多数派提交\n② 修复（让不一致被消除）：重试 / 补偿事务（TCC、Saga、冲正）/ 消息重投\n③ 检测（让不一致被发现）：对账 / 校验和比对 / 定时一致性巡检"}}]}],"exams":[{"kind":"choice","q":"关于异步 / 半同步 / 组复制的提交路径，下列说法正确的是","stem":"某订单库部署了 1 主 2 从。业务要求「主库宕机时已提交的订单不能丢」，运维把半同步参数设为 rpl_semi_sync_master_wait_for_slave_count = 2。 下面哪一项的表述是正确的？","opts":[{"k":"A","t":"半同步的含义是事务在从库已重放可见后才返回客户端，因此天然满足读己之写"},{"k":"B","t":"等待数设为 2 时，任一从库抖动都会让主库写入卡到超时才返回；等待数必须严格小于可用从库数"},{"k":"C","t":"半同步超时后会永久停留在异步状态，必须重启主库才能恢复"},{"k":"D","t":"组复制（MGR）与半同步的区别只是等待的从库个数不同，其余机制完全一致"}],"ans":"B","why":"A 错：半同步的 ACK 语义是「事务已到达至少一个从库（relay log / 已提交）」，不保证从库已重放可见，因此半同步不提供读己之写，会话级修复仍然必需。B 对：等待数等于从库数时，任一从库抖动都会让主库写入卡在 rpl_semi_sync_master_timeout 上，表现为「写入超时」而慢查询日志里查不到；等待数必须严格小于可用从库数。C 错：超时后确实会退化为…"},{"kind":"choice","q":"关于分片维度与扩容迁移量，下列说法正确的是","stem":"某系统现有 4 个分片，用 hash(key) % 4 路由。运维计划扩容。 结合本机实测数据（10000 个 key），下面哪一项正确？","opts":[{"k":"A","t":"扩容到 5 个分片与扩容到 8 个分片，迁移率相同，都约 100%"},{"k":"B","t":"取模扩容到 8 个分片迁移率恰为 50%，扩容到 5 个分片迁移率约 80%；一致性哈希在扩容到 5 个分片时只需约 2…"},{"k":"C","t":"一致性哈希在任何扩容场景下迁移率都严格小于取模，因为虚拟节点会吸收全部迁移"},{"k":"D","t":"范围分片在热点键分布下与哈希分片一样均衡，只是实现更简单"}],"ans":"B","why":"实测（examples/ex10）：取模 4→8 迁移 5000/10000 = 50.00%；取模 4→5 迁移 8010/10000 = 80.10%；哈希环 4→5 迁移 2146/10000 = 21.46%；哈希环 4→8 迁移 5051/10000 = 50.51%。A 错在「都约 100%」——取模 N→N+1 是约 N/(N+1)（80%），N→2N 恰好约 1…"},{"kind":"output","q":"写出雪花算法的位分配与容量指标，并计算给定参数下的 ID","stem":"某团队采用标准雪花算法，位分配为 1 符号位 + 41 时间戳位 + 10 机器位 + 12 序列位，自定义纪元 EPOCH = 1704067200000（毫秒）。 请回答三件事： 1. 单机每毫秒的最大发号量与单集群最大机器数各是多少？ 2. 41 位毫秒可支撑多少年（按 365 天/年计）？ 3. 已知 worker = 7、时间戳 ts = 1704067200123、seq = 0，按…","opts":[],"ans":"单机每毫秒最大发号量 = 2^12 = 4096（即 409.6 万/秒） 单集群最大机器数 = 2^10 = 1024 41 位毫秒可支撑 = 69 年 id = 515928064","why":"雪花算法的位分配决定了三个容量维度：时间跨度（41 位 ≈ 69 年）、节点规模（10 位 = 1024）、单机吞吐（12 位 = 4096/ms）。三者此消彼长，因为总位宽固定 63 位（1 位符号不使用），这是信息论约束。本题的数值与 examples/ex03 的实测输出互相印证（id[0] = 515928064）。"},{"kind":"output","q":"用 W + R > N 判定强一致，并给出容错能力","stem":"某多副本存储系统有 5 个副本。运维给出四组读写参数： (a) N=5, W=3, R=3 (b) N=5, W=2, R=3 (c) N=5, W=2, R=2 (d) N=3, W=2, R=1 请对每组判定「是否保证强一致」，并写出可容忍的写故障数与读故障数（写可用需存活 W 个节点，故容忍 N−W 个）。","opts":[],"ans":"(a) N=5 W=3 R=3 : W+R=6 > 5 -> 强一致 True ；容忍写故障 2 个、读故障 2 个 (b) N=5 W=2 R=3 : W+R=5 不 > 5 -> 强一致 False；容忍写故障 3 个、读故障 2 个 (c) N=5 W=2 R=2 : W+R=4 不 > 5 -> 强一致 Fal…","why":"判据 W + R > N 是「任意写集合与任意读集合必然相交」的充要条件（充分性用鸽巢原理，必要性用互补划分构造反例）。本机 ex09 已用组合枚举对同类 8 组参数逐例互证判据与枚举等价（全部 True）。 特别注意 (b)(c)(d) 三组的 W + R 恰好等于 N：此时读写集合可以完全不相交，读到的可能是不含本次写入的副本，因此不保证强一致。(c) 尤其容易误判——参数…"},{"kind":"coding","q":"实现带虚拟节点的一致性哈希环，并实测增删节点的影响面","stem":"请用 Python（仅标准库）实现一个一致性哈希环，满足： 1. 支持 add(node) / remove(node) / get(key)； 2. 每个物理节点映射为 V 个虚拟节点（默认 150）； 3. 不得使用 Python 内置 hash()（受 PYTHONHASHSEED 影响，结果不确定），请使用 zlib.crc32； 4. 对 10000 个 key，计算把 4 个节点扩到…","opts":[],"ans":"受影响 key = 2150 / 10000 = 0.2150 判据 |实测-理论| < 0.02 : True","why":"实现要点三处：① 用 zlib.crc32 而非内置 hash，保证跨进程结果确定；② 虚拟节点的点是 hash(node#i) 而不是把节点名本身放进环（否则一个节点只有一个点，负载会极度倾斜——本机 ex01 实测虚拟节点数 1 时 5 节点 key 分布为 [58, 37, 10, 129, 9766]，标准差 3883.2）；③ 查找用 bisect_right 找顺时…"},{"kind":"coding","q":"LeetCode 23 · 合并 K 个升序链表（跨分片 top-k 归并的同构问题）","stem":"给定 k 个升序链表，将它们合并为一个升序链表。 本题与本章「跨分片 top-k 归并」是同构问题：每个有序链表相当于一个分片返回的局部有序结果，合并所有链表相当于全局归并。请思考它与 examples/ex05 中「每分片取 top-k_local 再归并」的正确性条件k_local >= k 之间的关系。","opts":[],"ans":"import heapq def merge_k_lists(lists): \"\"\"lists: List[Optional[ListNode]] -> Optional[ListNode]\"\"\" heap = [] for i, node in enumerate(lists): if node is not Non…","why":"同构性说明：分片归并中每个分片是一个有序（按 score 排序）的流，取「局部 top-k_local」等价于从这个流里取前 k_local 个元素。全局 top-k 必然被包含在「各分片前 k 个」的并集中（因为任一全局第 j 名在其分片内排名 ≤ j ≤ k），这与 k 路归并「每次只需比较各流的当前头」的正确性是同一个道理。反过来，若某分片只返回前 k_local < k…"},{"kind":"fix_error","q":"修复读写分离路由引擎的顺序错误","stem":"下面的读写分离路由器有两个严重缺陷，会导致「事务内读走从库」和「写后读走从库（违反读己之写）」： python def route(req, replicas): sql = req['sql'].strip().lower() if sql.startswith(('select', 'show')): return replicas[0] # 缺陷 1 if req.get('in_tx'):…","opts":[],"ans":"WRITE_KW = ('insert', 'update', 'delete', 'replace') def route(req, replicas, lag_ms=0, max_lag_ms=500): sql = req['sql'].strip().lower() if req.get('in_tx'): r…","why":"路由引擎是「按优先级排序的判定链」，本质是一个有序规则表：越靠前的规则优先级越高。这类 bug 的共同特征是「规则都在，但顺序错了」，所以单测必须覆盖每条规则的最优先命中（用 assert 逐条钉住），而不能只测「某个写语句能路由到主库」。本机 ex11 的输出表就是这种逐条覆盖的形态。"},{"kind":"coding","q":"多数派选主模拟器：给定节点数与分区，判定是否脑裂","stem":"请实现一个选主判据函数，模拟如下规则： 1. 集群 N 个节点，quorum = N // 2 + 1； 2. 某分区内的候选者只有在获得该分区内所有存活节点的授权、且授权数 ≥ quorum 时才能当选； 3. 若两个分区各自都选出了主，则判定为脑裂。 请对下面三个场景输出「是否脑裂」： (A) 5 节点，1 个宕机，存活 4 个，quorum = 3 (B) 5 节点，分区为 {n1,n2}…","opts":[],"ans":"(A) 存活 4, quorum 3 -> 得票 4 >= 3 -> 当选 True ；脑裂 False (B) 少数派 {n1,n2} 得票 2 < 3 -> 当选 False 多数派 {n3,n4,n5} 得票 3 >= 3 -> 当选 True ；脑裂 False (C) 少数派 {n1,n2} 得票 2 >=…","why":"本题的工程延伸：即使选主规则正确，还必须有 fencing —— 旧主在失去仲裁后可能仍在接受写入，因此提升新主前必须先确认旧主已停止写入（顺序不能颠倒）。因为仅追加的日志一旦分叉就无法在不丢数据的前提下合并，这也是 CAP 中选 CP 时「宁可拒绝写也不能双写」的根本原因。另外 N 为偶数时多数派优势不增加（4 与 3 的 quorum 都是 3），所以集群节点数取奇数是更划…"}],"works":[{"h":"把「主从延迟」当成「数据丢失」","d":"异步复制下从库读到旧值是预期行为，不是故障（本机 ex06 实测：延迟 2 个操作时写后读从库得到 None）。真正需要处理的是延迟单调发散（从库重放速率 < 主库写入速率），判据是「重放速率 ≥ 写入速率」才收敛。误判方向会导致「明明只是延迟却去重搭从库」的资源浪费。"},{"h":"只看 Seconds_Behind_Master 判断复制健康","d":"该指标在主库空载时会归零、在 I/O 线程断开时变成 NULL（NULL 不是 0），且它比较的是主从两台机器的时钟（NTP 漂移会失真）。正确做法是额外上报 GTID 缺口（Retrieved_Gtid_Set 与 Executed_Gtid_Set 的差集）与「按业务表埋时间戳算出的真实延迟」。"},{"h":"把「半同步复制」说成「强一致」","d":"半同步的 ACK 语义是「事务已到达至少一个从库（relay log 或已提交）」，不保证你随后在从库能读到它。因此半同步仍不提供读己之写，会话级手段（写后读主 / 版本号等待 / 单调读）依然必需。"},{"h":"半同步参数设成「等待数 = 从库数」","d":"rpl_semi_sync_master_wait_for_slave_count 必须严格小于可用从库数量。设成 2 而只有 2 个从库时，任一从库抖动都会让主库写入卡到 rpl_semi_sync_master_timeout 才返回，业务侧表现为「写入莫名超时」，而慢查询日志里什么都看不到。"},{"h":"忽略半同步的静默降级","d":"超时（默认 10s，生产常压到 100ms~1s）后主库自动退化为异步，从库仍在跑、监控看起来正常，但系统已进入丢数据风险区。必须对 Rpl_semi_sync_master_status 与 Rpl_semi_sync_master_no_tx 建告警，否则降级可以持续数月无人发现。"},{"h":"从库不开 read_only，或只开 read_only 不开 super_read_onl…","d":"只设 read_only=1 时，持有 SUPER 权限的运维账号仍能写进去，造成静默数据分叉。且分叉通常只有在主从切换或对账时才会暴露。正确做法是两个都开，并禁止绕过主库写从库的脚本存在。"},{"h":"认为「按 id 范围切分片是均衡的」","d":"范围分片只对「均匀增长且访问均匀」的键成立。本机 ex02 实测：同一份倾斜键分布下，范围分片最大分片占比 80.0%、极差 7334（热点全压进 shard0），而哈希分片最大占比 25.8%、极差 121。用户 id、商品 id 这类有热点的键必须用哈希类方案。"},{"h":"认为「哈希取模扩容要重分布 100% 数据」","d":"不准确。精确结论：N→N+1 迁移约 N/(N+1)（4→5 实测 80.10%）；N→2N 恰好约 1/2（4→8 实测 50.00%）。这个区别直接决定容量规划：按 2 的幂规划分片数，就能让每次扩容只搬一半。"}],"asks":[{"q":"讲一下 MySQL 主从复制的完整流程。binlog 有哪几种格式，生产为什么用 ROW？","a":"链路（一段话说清）： 1. 主库把已提交事务按 binlog_format 序列化写入本地 binlog（仅追加）； 2. 从库 I/O 线程带位点或 GTID 集合向主库发 COM_BINLOG_DUMP； 3. 主库 dump 线程读 binlog 并推流； 4. 从库把事件落盘为 relay log； 5. 从库 SQL 线程（applier）读 relay log 顺序重放，更新已执行位点…","fu":["SHOW SLAVE STATUS 里 Slave_SQL_Running=No 且报 1032，你会怎么处理？为什么不…","从库为什么要同时开 read_only 和 super_read_only？只开前者会出什么事？"],"tag":"通用/阿里"},{"q":"主从延迟是怎么产生的？读写分离下「读己之写」怎么保证？","a":"延迟的五类成因： 1. 从库单线程重放（主库并发提交 vs 从库串行重放）→ 开 slave_parallel_workers + binlog_transaction_dependency_tracking=WRITESET； 2. 大事务（重放期间无法并行）→ 拆批； 3. 从库资源竞争（报表/备份占用 IO）→ 专用从库； 4. 主库突发写入 → 限流削峰； 5. 网络与 relay log…","fu":["半同步复制的 ACK 语义到底是什么？它能保证读己之写吗？","如果业务要求「任意时刻读到的都是最新已提交数据」，你会给出什么方案？代价是什么？"],"tag":"通用/阿里"},{"q":"分库分表怎么切？范围、哈希、一致性哈希、基因法分别适合什么场景？","a":"先明确：分片的本质是构造「查找键 → 存储单元」的映射，同时优化负载均衡、数据局部性、扩容迁移代价三个目标，三者不可同时最优。 | 维度 | 规则 | 均衡 | 局部性 | 扩容迁移 | 场景 | |---|---|---|---|---|---| | 范围 | 按 id/时间区间 | 差 | 好 | 好（追加区间） | 日志、账单（可归档） | | 哈希取模 | hash(k) % N | 好…","fu":["分片键有哪三条硬约束？为什么「不可变」这一条最容易被忽略？","跨分片 top-k 归并的正确性条件是什么？给一个反例。"],"tag":"通用/阿里"},{"q":"雪花算法的结构是什么？时钟回拨怎么处理？还有哪些分布式 ID 方案？","a":"结构（64 位）： 1 符号位（不用） + 41 时间戳位 + 10 机器位 + 12 序列位 单机每毫秒 = 2^12 = 4096 → 409.6 万/秒·节点 单集群节点 = 2^10 = 1024 41 位毫秒 ≈ 69 年 为什么时间戳放高位：这样 ID 的数值序 = 生成序（趋势递增），InnoDB 聚簇索引的插入点始终在 B+ 树右端，避免随机插入导致的页分裂与碎片 —— 这是「分布…","fu":["K8s 里机器号（workerId）怎么分配？为什么不能用 Pod IP 的哈希？","号段模式（Leaf-segment）的「双 buffer」解决什么问题？它的「有空洞」在什么业务下不可接受？"],"tag":"通用/美团"}]}];

